
const $=s=>document.querySelector(s), app=$("#app");
const getToken=()=>localStorage.getItem("masabaToken");
const getUser=()=>JSON.parse(localStorage.getItem("masabaUser")||"null");
const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
const toast=m=>{const x=$("#toast");x.textContent=m;x.classList.add("show");setTimeout(()=>x.classList.remove("show"),2600)};
const api=async(url,opt={})=>{const headers={...(opt.body instanceof FormData?{}:{"Content-Type":"application/json"}),...(opt.headers||{})};if(getToken())headers.Authorization="Bearer "+getToken();const r=await fetch(url,{...opt,headers});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||"Request failed");return d};
const roleLabel=r=>({admin:"Administrator",principal:"Principal",teacher:"Teacher",student:"Student",parent:"Parent"}[r]||r);
const fmtMoney=n=>"₦"+Number(n||0).toLocaleString();
const className=id=>window._classes?.find(x=>x.id===id)?.name||id||"—";
const subjectName=id=>window._subjects?.find(x=>x.id===id)?.name||id||"—";
document.body.addEventListener("click",e=>{const a=e.target.closest("a[href^='#']");if(a)$("#siteHeader").classList.remove("open")});
$("#menuBtn").onclick=()=>{const o=$("#siteHeader").classList.toggle("open");$("#menuBtn").setAttribute("aria-expanded",o)};
$("#loginBtn").onclick=()=>$("#modal").classList.add("show");
$("#closeModal").onclick=()=>$("#modal").classList.remove("show");
$("#modal").onclick=e=>{if(e.target.id==="modal")$("#modal").classList.remove("show")};
$("#year").textContent=new Date().getFullYear();

$("#loginForm").onsubmit=async e=>{e.preventDefault();try{const d=await api("/api/auth/login",{method:"POST",body:JSON.stringify({username:$("#loginUser").value,password:$("#loginPass").value})});localStorage.setItem("masabaToken",d.token);localStorage.setItem("masabaUser",JSON.stringify(d.user));$("#modal").classList.remove("show");toast("Signed in successfully");location.hash="portal";render()}catch(err){toast(err.message)}};

function sectionHead(eyebrow,title,text=""){return `<div class="sectionHead"><span class="eyebrow">${esc(eyebrow)}</span><h2>${esc(title)}</h2>${text?`<p>${esc(text)}</p>`:""}</div>`}
async function renderHome(){document.body.classList.remove("portalMode");const d=await publicData();window._classes=d.classes;window._subjects=d.subjects;app.innerHTML=home()}
async function news(){document.body.classList.remove("portalMode");const d=await publicData();return `<section class="section page">${sectionHead("NEWS","Latest school notices.","Public announcements from Masaba International Schools.")}<div class="grid3">${(d.announcements||[]).map(x=>`<article class="card"><span class="eyebrow">${esc(x.date)}</span><h3>${esc(x.title)}</h3><p class="muted">${esc(x.body)}</p><small>By ${esc(x.author||"School")}</small></article>`).join("")||`<div class="empty">No announcements published yet.</div>`}</div></section>`}
async function events(){document.body.classList.remove("portalMode");const d=await publicData();return `<section class="section page">${sectionHead("EVENTS","School calendar.","Important dates and activities.")}<div class="grid3">${(d.events||[]).map(x=>`<article class="card"><span class="eyebrow">${esc(x.date)}</span><h3>${esc(x.title)}</h3><p class="muted">${esc(x.description)}</p></article>`).join("")||`<div class="empty">No events published yet.</div>`}</div></section>`}

const tabs={
 admin:["Overview","Students","Teachers","Parents","Classes","Subjects","Results","Attendance","Assignments","Materials","Exams","Fees","Admissions","Announcements","Events","Gallery","Timetable","Payments","Bank","Messages","Users","Audit","Settings"],
 principal:["Overview","Students","Teachers","Parents","Classes","Subjects","Results","Attendance","Assignments","Materials","Exams","Fees","Admissions","Announcements","Events","Gallery","Timetable","Payments","Bank","Messages","Users","Audit","Settings"],
 teacher:["Overview","Students","Attendance","Results","Assignments","Materials","Exams","Timetable","Gallery","Bank","Messages"],
 student:["Overview","Subjects","Results","Attendance","Assignments","Materials","Exams","Timetable","Report"],
 parent:["Overview","Children","Results","Attendance","Fees","Messages","Assignments","Timetable","Report"]
};
let dashData=null, currentTab="Overview", examTimer=null, activeAttempt=null, questionDraft=[];
async function renderPortal(){if(!getToken()){document.body.classList.remove("portalMode");app.innerHTML=`<section class="section page">${sectionHead("DIGITAL CAMPUS","Portal login required.","Use the Portal Login button above to sign in.")}<button class="btn primary" onclick="$('#loginBtn').click()">Open Portal Login</button></section>`;return}document.body.classList.add("portalMode");if(getUser()?.mustChange){forcePasswordChange();return}dashData=await api("/api/dashboard");window._classes=dashData.classes||window._classes||await api("/api/classes");window._subjects=dashData.subjects||window._subjects||await api("/api/subjects");renderDash()}
function renderDash(){const u=getUser();const t=tabs[u.role]||[];app.innerHTML=`<section class="dashboard"><div class="dashTop"><div><span class="eyebrow">${esc(u.owner?"Proprietor":roleLabel(u.role))} PORTAL</span><h1>Welcome, ${esc(u.name||u.username)}</h1><p class="muted">Masaba International Schools Digital Campus · ${esc(u.owner?"Proprietor":roleLabel(u.role))}</p></div><div class="actionsRow"><button class="btn ghost" onclick="location.hash='home'">Public site</button><button class="btn ghost" onclick="changePasswordForm()">Change password</button><button class="btn primary" onclick="logout()">Sign out</button></div></div><div class="dashLayout"><aside class="side">${t.map(x=>`<button class="${currentTab===x?'active':''}" onclick="openTab('${x}')">${tabIcon(x)} ${x}</button>`).join("")}</aside><main id="dashContent" class="content"></main></div></section>`;openTab(currentTab)}
const tabIcon=t=>({Overview:"⌂",Students:"👨‍🎓",Teachers:"👩‍🏫",Parents:"👪",Classes:"🏫",Subjects:"📚",Results:"📊",Attendance:"✓",Assignments:"📝",Materials:"📖",Exams:"🖥️",Fees:"₦",Admissions:"📥",Announcements:"📣",Events:"📅",Audit:"🛡️",Users:"🔑",Messages:"💬",Gallery:"🖼️",Timetable:"🗓️",Payments:"💳",Bank:"🏦",Settings:"⚙️",Children:"👨‍👩‍👧",Report:"📄"}[t]||"•");
async function openTab(t){currentTab=t;const c=$("#dashContent");if(!c)return;document.querySelectorAll(".side button").forEach(b=>b.classList.toggle("active",b.textContent.includes(t)));try{const fn={Overview:tabOverview,Students:tabStudents,Teachers:tabTeachers,Parents:tabParents,Classes:tabClasses,Subjects:tabSubjects,Results:tabResults,Attendance:tabAttendance,Assignments:tabAssignments,Materials:tabMaterials,Exams:tabExams,Fees:tabFees,Admissions:tabAdmissions,Announcements:tabAnnouncements,Events:tabEvents,Users:tabUsers,Messages:tabMessages,Gallery:tabGallery,Timetable:tabTimetable,Payments:tabPayments,Bank:tabBank,Audit:tabAudit,Settings:tabSettings,Children:tabChildren,Report:tabReport}[t];if(fn)c.innerHTML=await fn();attachTabHandlers(t)}catch(e){c.innerHTML=`<div class="panel"><h3>Could not load this section</h3><p>${esc(e.message)}</p></div>`}}

function statCard(n,l){return `<div class="statCard"><b>${esc(n)}</b><small>${esc(l)}</small></div>`}
async function tabOverview(){const d=dashData,u=getUser();if(u.role==="student")return `${stats4(statCard(avg(d.results)+"%","Current average"),statCard(attRate(d.attendance)+"%","Attendance"),statCard(d.fees.filter(x=>x.status!=="Paid").length,"Outstanding fees"),statCard(d.exams.length,"Available exams"))}<div class="dashGrid"><div class="panel"><h3>My subjects</h3>${subjectChips(d.subjects)}</div><div class="panel"><h3>Academic results</h3>${resultTable(d.results)}</div></div>`;
if(u.role==="parent")return `${stats4(statCard(d.children.length,"Children"),statCard(avg(d.results)+"%","Average across records"),statCard(d.fees.filter(x=>x.status!=="Paid").length,"Outstanding fee records"),statCard("Active","Portal"))}<div class="dashGrid"><div class="panel"><h3>My children</h3>${d.children.map(s=>`<div class="listItem"><span><b>${esc(s.name)}</b><small class="mini">${esc(s.admissionNo)} · ${className(s.classId)}</small></span><button class="btn ghost" onclick="viewStudent('${s.id}')">View</button></div>`).join("")}</div><div class="panel"><h3>Recent results</h3>${resultTable(d.results)}</div></div>`;
if(u.role==="teacher")return `${stats4(statCard(d.students.length,"Assigned students"),statCard(d.teacher?.classIds?.length||0,"Classes"),statCard(d.assignments.length,"My assignments"),statCard(d.materials.length,"My materials"))}<div class="dashGrid"><div class="panel"><h3>Teaching profile</h3><p><b>${esc(d.teacher?.name)}</b></p><p class="muted">${(d.teacher?.classIds||[]).map(className).join(", ")||"No classes assigned"}<br>${(d.teacher?.subjectIds||[]).map(subjectName).join(", ")||"No subjects assigned"}</p></div><div class="panel"><h3>Quick actions</h3><div class="toolbar"><button class="btn primary" onclick="openTab('Attendance')">Take attendance</button><button class="btn ghost" onclick="openTab('Results')">Enter results</button><button class="btn ghost" onclick="openTab('Exams')">Manage CBT</button></div></div></div>`;
return `${stats4(statCard(d.stats.students,"Students"),statCard(d.stats.teachers,"Teachers"),statCard(d.stats.parents,"Parents"),statCard(d.stats.admissions,"New admissions"))}${d.stats.pendingPayments?`<div class="panel"><b>💳 ${d.stats.pendingPayments} payment(s) waiting for confirmation</b> <button class="btn primary" onclick="openTab('Payments')">Review</button></div>`:""}<div class="dashGrid"><div class="panel"><h3>School operations</h3><div class="features"><div>✓ Individual student subjects</div><div>✓ Results & report cards</div><div>✓ Attendance</div><div>✓ Assignments & materials</div><div>✓ Timed CBT & auto-submit</div><div>✓ Fees & admissions</div><div>✓ Announcements & events</div><div>✓ Audit trail</div></div></div><div class="panel"><h3>Recent announcements</h3>${(d.announcements||[]).map(a=>`<div class="listItem"><span><b>${esc(a.title)}</b><small class="mini">${esc(a.date)}</small></span></div>`).join("")||"<div class='empty'>No announcements.</div>"}</div></div>`}
const stats4=(a,b,c,d)=>`<div class="statGrid">${a}${b}${c}${d}</div>`;
const avg=rows=>rows?.length?Math.round(rows.reduce((s,x)=>s+Number(x.score||0),0)/rows.length):0;
const attRate=rows=>rows?.length?Math.round(rows.filter(x=>x.status==="Present").length/rows.length*100):100;
const subjectChips=rows=>(rows||[]).length?`<div class="actionsRow">${rows.map(s=>`<span class="pill">${esc(s.name)}</span>`).join("")}</div>`:"<div class='empty'>No subjects assigned.</div>";
const resultTable=rows=>rows?.length?`<div class="tableWrap"><table class="table"><tr><th>Student</th><th>Subject</th><th>CA</th><th>Exam</th><th>Total</th><th>Grade</th></tr>${rows.slice(-20).map(r=>`<tr><td>${esc(r.student||"")}</td><td>${esc(r.subject||subjectName(r.subjectId))}</td><td>${r.ca??"—"}</td><td>${r.exam??"—"}</td><td>${r.score??0}%</td><td><span class="pill">${esc(r.grade)}</span></td></tr>`).join("")}</table></div>`:"<div class='empty'>No results recorded.</div>";

async function loadAll(){window._classes=await api("/api/classes");window._subjects=await api("/api/subjects")}
async function tabStudents(){const rows=await api("/api/students");const u=getUser();window._students=rows; if(["admin","principal"].includes(u.role))window._parents=await api("/api/parents");return `<div class="panel"><div class="toolbar">${["admin","principal"].includes(u.role)?`<button class="btn primary" onclick="studentForm()">+ Add student</button>`:""}<button class="btn ghost" onclick="loadAll().then(()=>openTab('Students'))">Refresh</button></div><div class="tableWrap"><table class="table"><tr><th>Admission</th><th>Name</th><th>Class</th><th>Subjects</th><th>Parent</th><th>Status</th><th>Action</th></tr>${rows.map(s=>`<tr><td>${esc(s.admissionNo)}</td><td><b>${esc(s.name)}</b></td><td>${esc(className(s.classId))}</td><td>${(s.subjectIds||[]).length}</td><td>${esc(window._parents?.find(p=>p.id===s.parentId)?.name||s.parentId||"—")}</td><td><span class="pill">${esc(s.status)}</span></td><td><div class="actionsRow">${["admin","principal"].includes(u.role)?`<button class="btn ghost" onclick="studentForm('${s.id}')">Edit</button>`:""}${["admin","principal","teacher"].includes(u.role)?`<button class="btn ghost" onclick="subjectManager('${s.id}')">Subjects</button>`:""}<button class="btn ghost" onclick="viewReport('${s.id}')">Report</button></div></td></tr>`).join("")}</table></div></div>`}
async function studentForm(id){const rows=await api("/api/students?all=1");const s=rows.find(x=>x.id===id)||{name:"",admissionNo:"",classId:"kindergarten",gender:"",dob:"",parentId:"",status:"Active",subjectIds:[]};const parents=window._parents||await api("/api/parents");const subs=await api("/api/subjects");const canEditSubjects=["admin","principal","teacher"].includes(getUser().role);const teacherClassAllowed=getUser().role!=="teacher"||((dashData?.teacher?.classIds||[]).includes(s.classId));const subjectEditor=canEditSubjects&&teacherClassAllowed;$("#dashContent").innerHTML=`<div class="panel"><div class="toolbar"><button class="btn ghost" onclick="openTab('Students')">← Back</button></div><h3>${id?"Edit":"Add"} student</h3><form id="studentForm" class="formGrid"><label>Full name<input name="name" value="${esc(s.name)}" required></label><label>Admission number<input name="admissionNo" value="${esc(s.admissionNo)}"></label><label>Class<select name="classId" id="studentClass">${window._classes.map(c=>`<option value="${c.id}" ${s.classId===c.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select></label><label>Parent<select name="parentId"><option value="">Not linked</option>${parents.map(p=>`<option value="${p.id}" ${s.parentId===p.id?"selected":""}>${esc(p.name)}</option>`).join("")}</select></label><label>Gender<select name="gender"><option>—</option><option ${s.gender==="Male"?"selected":""}>Male</option><option ${s.gender==="Female"?"selected":""}>Female</option></select></label><label>Date of birth<input name="dob" type="date" value="${esc(s.dob)}"></label><label>School email (optional)<input name="schoolEmail" type="email" value="${esc(s.schoolEmail||"")}"></label><label>Status<select name="status"><option ${s.status==="Active"?"selected":""}>Active</option><option ${s.status==="Inactive"?"selected":""}>Inactive</option></select></label>${subjectEditor?`<div class="fullRow subjectEditor"><h4>Subjects for this student</h4><p class="muted mini">Tick only the subjects this student actually takes. This overrides the class default for this student.</p><div class="checkGrid">${subs.filter(x=>x.active!==false).map(x=>`<label class="check"><input type="checkbox" name="subjectIds" value="${x.id}" ${(s.subjectIds||[]).includes(x.id)?"checked":""}>${esc(x.name)}</label>`).join("")}</div></div>`:""}<button class="btn primary fullRow">Save student</button></form></div>`;$("#studentForm").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),b=Object.fromEntries(fd.entries());if(subjectEditor)b.subjectIds=[...e.target.querySelectorAll("input[name=subjectIds]:checked")].map(x=>x.value);try{if(id)await api("/api/students/"+id,{method:"PATCH",body:JSON.stringify(b)});else await api("/api/students",{method:"POST",body:JSON.stringify(b)});toast("Student saved");openTab("Students")}catch(err){toast(err.message)}}}
async function subjectManager(id){const s=(await api("/api/students")).find(x=>x.id===id);const subs=await api("/api/subjects");$("#dashContent").innerHTML=`<div class="panel"><div class="toolbar"><button class="btn ghost" onclick="openTab('Students')">← Back</button></div><span class="eyebrow">INDIVIDUAL SUBJECTS</span><h3>${esc(s.name)}</h3><p class="muted">Teachers, principal and administrator can add or remove subjects for this student.</p><form id="subjectForm"><div class="checkGrid">${subs.filter(x=>x.active!==false).map(x=>`<label class="check"><input type="checkbox" name="subjectIds" value="${x.id}" ${(s.subjectIds||[]).includes(x.id)?"checked":""}>${esc(x.name)}</label>`).join("")}</div><button class="btn primary" style="margin-top:18px">Save subject selection</button></form></div>`;$("#subjectForm").onsubmit=async e=>{e.preventDefault();const ids=[...e.target.querySelectorAll("input:checked")].map(x=>x.value);try{await api("/api/students/"+id+"/subjects",{method:"PUT",body:JSON.stringify({subjectIds:ids})});toast("Subject selection updated");openTab("Students")}catch(err){toast(err.message)}}}
async function viewStudent(id){const d=await api("/api/students/"+id);$("#dashContent").innerHTML=`<div class="panel"><div class="toolbar"><button class="btn ghost" onclick="openTab('Children')">← Back</button></div><h3>${esc(d.name)}</h3><p class="muted">${esc(d.admissionNo)} · ${esc(d.class?.name||className(d.classId))}</p><h4>Subjects</h4>${subjectChips(d.subjects)}<h4>Parent</h4><p>${esc(d.parent?.name||"Not linked")} ${d.parent?.phone?`· ${esc(d.parent.phone)}`:""}</p><h4>Quick links</h4><div class="toolbar"><button class="btn primary" onclick="viewReport('${d.id}')">View report card</button></div></div>`}
async function tabTeachers(){const rows=await api("/api/teachers");return `<div class="panel"><div class="toolbar">${["admin","principal"].includes(getUser().role)?`<button class="btn primary" onclick="teacherForm()">+ Add teacher</button>`:""}<button class="btn ghost" onclick="openTab('Teachers')">Refresh</button></div><div class="tableWrap"><table class="table"><tr><th>Staff ID</th><th>Name</th><th>Classes</th><th>Subjects</th><th>Email</th><th>Status</th><th></th></tr>${rows.map(t=>`<tr><td>${esc(t.staffId)}</td><td>${esc(t.name)}</td><td>${(t.classIds||[]).map(className).join(", ")}</td><td>${(t.subjectIds||[]).map(subjectName).join(", ")}</td><td>${esc(t.email||"—")}</td><td>${esc(t.status)}</td><td><button class="btn ghost" onclick="contactEdit('teacher','${t.id}')">Edit</button></td></tr>`).join("")}</table></div></div>`}
async function teacherForm(){const s={name:"",staffId:"",email:"",phone:"",classIds:[],subjectIds:[]};$("#dashContent").innerHTML=personForm("teacher",s);$("#personForm").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),b={name:fd.get("name"),staffId:fd.get("staffId"),email:fd.get("email"),schoolEmail:fd.get("schoolEmail")||"",phone:fd.get("phone"),classIds:[...e.target.querySelectorAll("input[name=classIds]:checked")].map(x=>x.value),subjectIds:[...e.target.querySelectorAll("input[name=subjectIds]:checked")].map(x=>x.value)};try{await api("/api/teachers",{method:"POST",body:JSON.stringify(b)});toast("Teacher saved");openTab("Teachers")}catch(err){toast(err.message)}}}
function personForm(type,s){const isT=type==="teacher";return `<div class="panel"><button class="btn ghost" onclick="openTab('${isT?"Teachers":"Parents"}')">← Back</button><h3>Add ${isT?"teacher":"parent"}</h3><form id="personForm" class="formGrid"><label>Name<input name="name" required></label><label>${isT?"Staff ID":"Phone"}<input name="${isT?"staffId":"phone"}"></label><label>Email<input name="email" type="email"></label>${isT?`<label>School email (optional)<input name="schoolEmail" type="email"></label>`:""}${isT?`<label>Phone<input name="phone"></label>`:""}${isT?`<label>Classes<div class="checkGrid">${window._classes.map(c=>`<label class="check"><input type="checkbox" name="classIds" value="${c.id}">${esc(c.name)}</label>`).join("")}</div></label><label>Subjects<div class="checkGrid">${window._subjects.map(c=>`<label class="check"><input type="checkbox" name="subjectIds" value="${c.id}">${esc(c.name)}</label>`).join("")}</div></label>`:""}<button class="btn primary fullRow">Save</button></form></div>`}
async function tabParents(){const rows=await api("/api/parents");window._parents=rows;return `<div class="panel"><div class="toolbar"><button class="btn primary" onclick="parentForm()">+ Add parent</button></div><div class="tableWrap"><table class="table"><tr><th>Name</th><th>Phone</th><th>Email</th><th>Children</th><th></th></tr>${rows.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.phone)}</td><td>${esc(p.email)}</td><td>${(p.studentIds||[]).length}</td><td><button class="btn ghost" onclick="contactEdit('parent','${p.id}')">Edit</button></td></tr>`).join("")}</table></div></div>`}
async function parentForm(){await loadAll();$("#dashContent").innerHTML=personForm("parent",{});$("#personForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.studentIds=[];try{await api("/api/parents",{method:"POST",body:JSON.stringify(b)});toast("Parent saved");openTab("Parents")}catch(err){toast(err.message)}}}
async function classForm(){const name=prompt("Class name, e.g. Primary 1");if(!name)return;const section=prompt("Section, e.g. Primary")||"Other";try{await api("/api/classes",{method:"POST",body:JSON.stringify({name,section})});toast("Class added");openTab("Classes")}catch(e){toast(e.message)}}
async function subjectForm(){const name=prompt("Subject name");if(!name)return;try{await api("/api/subjects",{method:"POST",body:JSON.stringify({name})});toast("Subject added");openTab("Subjects")}catch(e){toast(e.message)}}
async function tabResults(){const rows=await api("/api/results");if(["admin","principal","teacher"].includes(getUser().role))return `<div class="panel"><div class="toolbar"><button class="btn primary" onclick="resultForm()">+ Enter result</button></div>${resultTable(rows)}</div>`;return `<div class="panel"><h3>Academic results</h3>${resultTable(rows)}</div>`}
async function resultForm(){const students=await api("/api/students");const subjects=await api("/api/subjects");$("#dashContent").innerHTML=`<div class="panel"><button class="btn ghost" onclick="openTab('Results')">← Back</button><h3>Enter academic result</h3><form id="resultForm" class="formGrid"><label>Student<select name="studentId">${students.map(s=>`<option value="${s.id}">${esc(s.name)} — ${esc(s.admissionNo)}</option>`).join("")}</select></label><label>Subject<select name="subjectId">${subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join("")}</select></label><label>CA score (0–40)<input name="ca" type="number" min="0" max="40" value="25"></label><label>Exam score (0–60)<input name="exam" type="number" min="0" max="60" value="60"></label><label>Term<select name="term"><option>First Term</option><option>Second Term</option><option>Third Term</option></select></label><label>Published<select name="published"><option value="true">Yes</option><option value="false">No</option></select></label><label class="fullRow">Remark<textarea name="remark"></textarea></label><button class="btn primary fullRow">Save result</button></form></div>`;$("#resultForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.ca=Number(b.ca);b.exam=Number(b.exam);b.published=b.published==="true";try{await api("/api/results",{method:"POST",body:JSON.stringify(b)});toast("Result saved");openTab("Results")}catch(err){toast(err.message)}}}
async function tabAttendance(){const students=await api("/api/students");window._students=students;const rows=await api("/api/attendance");if(getUser().role==="teacher")return `<div class="panel"><h3>Take attendance</h3><form id="attendanceForm"><label>Date<input id="attDate" type="date" value="${new Date().toISOString().slice(0,10)}"></label><div class="tableWrap" style="margin-top:15px"><table class="table"><tr><th>Student</th><th>Class</th><th>Status</th></tr>${students.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(className(s.classId))}</td><td><select data-student="${s.id}"><option>Present</option><option>Absent</option><option>Late</option></select></td></tr>`).join("")}</table></div><button class="btn primary">Save attendance</button></form></div>`;return `<div class="panel"><h3>Attendance records</h3>${rows.length?`<div class="tableWrap"><table class="table"><tr><th>Date</th><th>Student</th><th>Status</th></tr>${rows.slice(-100).reverse().map(r=>`<tr><td>${esc(r.date)}</td><td>${esc((awaitNameStudent(r.studentId)))}</td><td><span class="pill">${esc(r.status)}</span></td></tr>`).join("")}</table></div>`:"<div class='empty'>No attendance records yet.</div>"}</div>`}
function awaitNameStudent(id){return window._students?.find(s=>s.id===id)?.name||id}
async function tabAssignments(){const rows=await api("/api/assignments");const u=getUser();return `<div class="panel"><div class="toolbar">${["admin","principal","teacher"].includes(u.role)?`<button class="btn primary" onclick="assignmentForm()">+ New assignment</button>`:""}</div>${rows.length?`<div class="grid3">${rows.map(a=>`<article class="card"><span class="eyebrow">${esc(className(a.classId))}</span><h3>${esc(a.title)}</h3><p class="muted">${esc(a.description)}</p><small>${esc(subjectName(a.subjectId))} · Due ${esc(a.dueDate||"—")}</small></article>`).join("")}</div>`:"<div class='empty'>No assignments yet.</div>"}</div>`}
async function assignmentForm(){const b=`<div class="panel"><button class="btn ghost" onclick="openTab('Assignments')">← Back</button><h3>Create assignment</h3><form id="assignmentForm" class="formGrid"><label>Title<input name="title" required></label><label>Class<select name="classId">${window._classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select></label><label>Subject<select name="subjectId">${window._subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join("")}</select></label><label>Due date<input name="dueDate" type="date"></label><label class="fullRow">Description<textarea name="description"></textarea></label><button class="btn primary fullRow">Publish assignment</button></form></div>`;$("#dashContent").innerHTML=b;$("#assignmentForm").onsubmit=async e=>{e.preventDefault();try{await api("/api/assignments",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});toast("Assignment created");openTab("Assignments")}catch(err){toast(err.message)}}}
async function tabMaterials(){const rows=await api("/api/materials");return `<div class="panel"><div class="toolbar">${["admin","principal","teacher"].includes(getUser().role)?`<button class="btn primary" onclick="materialForm()">+ Add material</button>`:""}</div>${rows.length?`<div class="grid3">${rows.map(m=>`<article class="card"><span class="eyebrow">${esc(subjectName(m.subjectId))}</span><h3>${esc(m.title)}</h3><p class="muted">${esc(className(m.classId))}</p>${m.url?`<a class="btn ghost" href="${esc(m.url)}" target="_blank">Open material</a>`:""}</article>`).join("")}</div>`:"<div class='empty'>No learning materials yet.</div>"}</div>`}
async function materialForm(){const b=`<div class="panel"><button class="btn ghost" onclick="openTab('Materials')">← Back</button><h3>Add learning material</h3><form id="materialForm" class="formGrid"><label>Title<input name="title" required></label><label>Class<select name="classId">${window._classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select></label><label>Subject<select name="subjectId">${window._subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join("")}</select></label><label>Link / file URL<input name="url" placeholder="/uploads/... or https://..."></label><button class="btn primary fullRow">Save material</button></form></div>`;$("#dashContent").innerHTML=b;$("#materialForm").onsubmit=async e=>{e.preventDefault();try{await api("/api/materials",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});toast("Material saved");openTab("Materials")}catch(err){toast(err.message)}}}
async function tabExams(){const rows=await api("/api/exams");const attempts=getUser().role==="student"?[]:await api("/api/exam-attempts");return `<div class="panel"><div class="toolbar">${["admin","principal","teacher"].includes(getUser().role)?`<button class="btn primary" onclick="examForm()">+ Create CBT exam</button>`:""}</div>${getUser().role==="student"?rows.map(e=>`<div class="listItem"><span><b>${esc(e.title)}</b><small class="mini">${esc(subjectName(e.subjectId))} · ${e.durationMinutes} minutes</small></span><button class="btn primary" onclick="startExam('${e.id}')">Start</button></div>`).join("")||"<div class='empty'>No CBT exams are assigned to you.</div>":`<h3>CBT exams</h3><div class="tableWrap"><table class="table"><tr><th>Exam</th><th>Class</th><th>Subject</th><th>Duration</th><th>Status</th><th>Attempts</th></tr>${rows.map(e=>`<tr><td>${esc(e.title)}</td><td>${esc(className(e.classId))}</td><td>${esc(subjectName(e.subjectId))}</td><td>${e.durationMinutes}m</td><td><span class="pill">${esc(e.status)}</span></td><td>${attempts.filter(a=>a.examId===e.id).length}</td></tr>`).join("")}</table></div>`}</div>`}
async function examForm(){questionDraft=[];$("#dashContent").innerHTML=`<div class="panel"><button class="btn ghost" onclick="openTab('Exams')">← Back</button><h3>Create timed CBT examination</h3><form id="examForm" class="formGrid"><label>Exam title<input name="title" required></label><label>Duration (minutes)<input name="durationMinutes" type="number" min="1" value="30"></label><label>Class<select name="classId">${window._classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select></label><label>Subject<select name="subjectId">${window._subjects.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join("")}</select></label><label>Status<select name="status"><option value="draft">Draft</option><option value="published">Published</option></select></label><label>Max attempts<input name="maxAttempts" type="number" min="1" value="1"></label><label>Start time<input name="startAt" type="datetime-local"></label><label>End time<input name="endAt" type="datetime-local"></label><label class="fullRow">Instructions<textarea name="description"></textarea></label><div class="fullRow"><h4>Questions</h4><div id="questionList" class="list"></div><button type="button" class="btn ghost" onclick="addQuestion()">+ Add question</button></div><button class="btn primary fullRow">Create exam</button></form></div>`;addQuestion();$("#examForm").onsubmit=async e=>{e.preventDefault();if(!questionDraft.length)return toast("Add at least one question");const b=Object.fromEntries(new FormData(e.target).entries());b.durationMinutes=Number(b.durationMinutes);b.maxAttempts=Number(b.maxAttempts);b.questions=questionDraft;try{await api("/api/exams",{method:"POST",body:JSON.stringify(b)});toast("Exam created");openTab("Exams")}catch(err){toast(err.message)}}}
function addQuestion(){const i=questionDraft.length;questionDraft.push({id:"q"+Date.now()+i,text:"",options:["","","",""],answer:0,marks:1});renderQuestions()}
function renderQuestions(){const el=$("#questionList");if(!el)return;el.innerHTML=questionDraft.map((q,i)=>`<div class="card"><div class="actionsRow"><b>Question ${i+1}</b><button type="button" class="danger" onclick="removeQuestion(${i})">Remove</button></div><label>Question<input value="${esc(q.text)}" oninput="questionDraft[${i}].text=this.value"></label><div class="formGrid" style="margin-top:10px">${q.options.map((o,j)=>`<label>Option ${j+1}<input value="${esc(o)}" oninput="questionDraft[${i}].options[${j}]=this.value"></label>`).join("")}</div><label style="margin-top:10px">Correct option<select onchange="questionDraft[${i}].answer=Number(this.value)">${q.options.map((_,j)=>`<option value="${j}" ${q.answer===j?"selected":""}>Option ${j+1}</option>`).join("")}</select></label></div>`).join("")}
function removeQuestion(i){questionDraft.splice(i,1);renderQuestions()}
async function startExam(id){try{const d=await api("/api/exams/"+id+"/start",{method:"POST"});activeAttempt=d;renderExam(d)}catch(e){toast(e.message)}}
function renderExam(d){document.body.classList.add("portalMode");clearInterval(examTimer);const end=new Date(d.deadline).getTime();app.innerHTML=`<section class="dashboard"><div class="dashTop"><div><span class="eyebrow">CBT EXAMINATION</span><h1>${esc(d.exam.title)}</h1><p class="muted">${esc(d.exam.description||"Timed examination")}</p></div><div class="timer" id="timer"></div></div><div class="panel"><form id="examLive">${d.exam.questions.map((q,i)=>`<div class="examQuestion"><b>${i+1}. ${esc(q.text)}</b>${q.options.map((o,j)=>`<label class="option"><input type="radio" name="${q.id}" value="${j}"> ${esc(o)}</label>`).join("")}</div>`).join("")}<button class="btn primary">Submit exam</button></form></div></section>`;$("#examLive").onsubmit=e=>{e.preventDefault();submitExam(false)};const tick=()=>{const s=Math.max(0,Math.floor((end-Date.now())/1000));$("#timer").textContent=`${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`;if(s<=0){clearInterval(examTimer);submitExam(true)}};tick();examTimer=setInterval(tick,500)}
async function submitExam(auto){clearInterval(examTimer);const f=$("#examLive"),answers={};if(f)new FormData(f).forEach((v,k)=>answers[k]=Number(v));try{for(const [questionId,answer] of Object.entries(answers))await api("/api/exams/attempts/"+activeAttempt.attemptId+"/answer",{method:"POST",body:JSON.stringify({questionId,answer})});const r=await api("/api/exams/attempts/"+activeAttempt.attemptId+"/submit",{method:"POST",body:"{}"});app.innerHTML=`<section class="section"><div class="panel"><span class="eyebrow">EXAM COMPLETE</span><h2>${auto?"Time expired — automatically submitted":"Exam submitted successfully"}</h2><div class="resultBig">${r.score}/${r.total}</div><p class="muted" style="text-align:center">Your attempt has been recorded.</p><button class="btn primary" onclick="location.hash='portal';render()">Back to portal</button></div></section>`}catch(e){toast(e.message)}}
async function tabFees(){const rows=await api("/api/fees");return `<div class="panel"><div class="toolbar">${["admin","principal"].includes(getUser().role)?`<button class="btn primary" onclick="feeForm()">+ Add fee record</button>`:""}</div><div class="tableWrap"><table class="table"><tr><th>Student</th><th>Item</th><th>Amount</th><th>Paid</th><th>Balance</th><th>Status</th></tr>${rows.map(f=>`<tr><td>${esc((window._students||[]).find(s=>s.id===f.studentId)?.name||f.studentId)}</td><td>${esc(f.item)}</td><td>${fmtMoney(f.amount)}</td><td>${fmtMoney(f.paid)}</td><td>${fmtMoney(Number(f.amount)-Number(f.paid))}</td><td><span class="pill">${esc(f.status)}</span></td></tr>`).join("")}</table></div></div>`}
async function feeForm(){const students=await api("/api/students");$("#dashContent").innerHTML=`<div class="panel"><button class="btn ghost" onclick="openTab('Fees')">← Back</button><h3>Add fee record</h3><form id="feeForm" class="formGrid"><label>Student<select name="studentId">${students.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join("")}</select></label><label>Item<input name="item" value="School fees"></label><label>Amount<input name="amount" type="number" min="0"></label><label>Paid<input name="paid" type="number" min="0" value="0"></label><label>Due date<input name="dueDate" type="date"></label><button class="btn primary fullRow">Save fee</button></form></div>`;$("#feeForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());try{await api("/api/fees",{method:"POST",body:JSON.stringify(b)});toast("Fee record saved");openTab("Fees")}catch(err){toast(err.message)}}}
async function tabAdmissions(){const rows=await api("/api/admissions");return `<div class="panel"><h3>Admission enquiries</h3>${rows.length?rows.map(a=>`<div class="listItem"><span><b>${esc(a.studentName)}</b><small class="mini">${esc(a.parentName)} · ${esc(a.phone)} · ${esc(className(a.classApplying))}${a.priorSchool?` · Previous: ${esc(a.priorSchool)}${a.priorGrade?" ("+esc(a.priorGrade)+")":""}`:""}</small></span><span class="actionsRow"><span class="pill">${esc(a.status)}</span>${a.status==="New"?`<button class="btn ghost" onclick="updateAdmission('${a.id}','Reviewed')">Review</button><button class="btn primary" onclick="updateAdmission('${a.id}','Accepted')">Accept</button>`:""}</span></div>`).join(""):"<div class='empty'>No admission enquiries yet.</div>"}</div>`}
async function updateAdmission(id,status){try{await api("/api/admissions/"+id,{method:"PATCH",body:JSON.stringify({status})});toast("Admission updated");openTab("Admissions")}catch(e){toast(e.message)}}
async function tabAnnouncements(){const rows=await api("/api/announcements");return `<div class="panel"><div class="toolbar"><button class="btn primary" onclick="announcementForm()">+ New announcement</button></div>${rows.map(a=>`<div class="listItem"><span><b>${esc(a.title)}</b><small class="mini">${esc(a.date)} · ${esc(a.author)}</small><br><span class="muted">${esc(a.body)}</span></span>${["admin","principal"].includes(getUser().role)?`<button class="danger" onclick="deleteAnnouncement('${a.id}')">Delete</button>`:""}</div>`).join("")||"<div class='empty'>No announcements.</div>"}</div>`}
async function announcementForm(){const title=prompt("Announcement title");if(!title)return;const body=prompt("Announcement message")||"";const emailParents=isMgmt()&&confirm("Also email this announcement to all parents who have an email address?");try{const r=await api("/api/announcements",{method:"POST",body:JSON.stringify({title,body,emailParents})});toast(emailParents?`Published. Emailed ${r.emailed||0} parent(s).`:"Announcement published");openTab("Announcements")}catch(e){toast(e.message)}}
async function deleteAnnouncement(id){if(!confirm("Delete this announcement?"))return;try{await api("/api/announcements/"+id,{method:"DELETE"});toast("Deleted");openTab("Announcements")}catch(e){toast(e.message)}}
async function tabEvents(){const rows=await api("/api/events");return `<div class="panel"><div class="toolbar"><button class="btn primary" onclick="eventForm()">+ Add event</button></div><div class="grid3">${rows.map(e=>`<article class="card"><span class="eyebrow">${esc(e.date)}</span><h3>${esc(e.title)}</h3><p class="muted">${esc(e.description)}</p></article>`).join("")||"<div class='empty'>No events.</div>"}</div></div>`}
async function eventForm(){const title=prompt("Event title");if(!title)return;const date=prompt("Date YYYY-MM-DD",new Date().toISOString().slice(0,10));const description=prompt("Description")||"";try{await api("/api/events",{method:"POST",body:JSON.stringify({title,date,description})});toast("Event added");openTab("Events")}catch(e){toast(e.message)}}
async function tabAudit(){const rows=await api("/api/audit");return `<div class="panel"><h3>Audit trail</h3><div class="tableWrap"><table class="table"><tr><th>Time</th><th>User</th><th>Role</th><th>Action</th><th>Details</th></tr>${rows.map(a=>`<tr><td>${new Date(a.at).toLocaleString()}</td><td>${esc(a.user)}</td><td>${esc(a.role)}</td><td>${esc(a.action)}</td><td>${esc(a.details)}</td></tr>`).join("")}</table></div></div>`}
async function tabSettings(){const s=await api("/api/settings");return `<div class="panel"><h3>School settings</h3><p class="muted">These values can be changed without editing the website code.</p><form id="settingsForm" class="formGrid"><label>School name<input name="schoolName" value="${esc(s.schoolName)}"></label><label>Motto<input name="motto" value="${esc(s.motto)}"></label><label>Academic session<input name="session" value="${esc(s.session)}"></label><label>Current term<select name="term">${["First Term","Second Term","Third Term"].map(x=>`<option ${s.term===x?"selected":""}>${x}</option>`).join("")}</select></label><label class="fullRow">Address<input name="address" value="${esc(s.address)}"></label><label>Emails<input name="emails" value="${esc((s.emails||[]).join(", "))}"></label><label>Phone numbers<input name="phones" value="${esc((s.phones||[]).join(", "))}"></label><label class="fullRow">Email that receives payment and bank-change alerts<input name="notifyEmail" type="email" value="${esc(s.notifyEmail||"")}"></label><button class="btn primary fullRow">Save settings</button></form></div><div class="panel"><h4>Homepage image</h4><p class="muted mini">This photo appears at the top of the school website. Choose a clear landscape photo.</p><img src="${esc(s.heroImage||"/assets/hero.jpg")}" alt="Current homepage image" style="max-width:320px;width:100%;border-radius:12px;display:block;margin:8px 0"><input type="file" id="heroFile" accept="image/*"><div class="actionsRow" style="margin-top:10px"><button class="btn primary" onclick="uploadHero()">Upload new image</button><button class="btn ghost" onclick="resetHero()">Use default image</button></div></div>`}
async function tabChildren(){const d=dashData;return `<div class="panel"><h3>My children</h3>${d.children.map(s=>`<div class="listItem"><span><b>${esc(s.name)}</b><small class="mini">${esc(s.admissionNo)} · ${esc(className(s.classId))} · ${(s.subjectIds||[]).length} subjects</small></span><button class="btn ghost" onclick="viewStudent('${s.id}')">View</button></div>`).join("")}</div>`}
async function tabReport(){const u=getUser();const id=u.role==="student"?u.personId:(dashData.children?.[0]?.id);if(!id)return "<div class='panel'><div class='empty'>No student available.</div></div>";return reportMarkup(await api("/api/report/"+id))}
async function viewReport(id){$("#dashContent").innerHTML=reportMarkup(await api("/api/report/"+id))}
function reportMarkup(d){return `<div class="reportPrint"><button class="btn primary" onclick="window.print()">Print / Save PDF</button></div><div class="report"><div class="reportHead"><img class="reportLogo" src="/assets/logo.jpg"><h2>${esc(d.school.schoolName)}</h2><b>${esc(d.school.motto)}</b><p class="muted">${esc(d.school.address)}</p><h3>STUDENT REPORT CARD</h3></div><div class="reportMeta"><div><b>Student:</b> ${esc(d.student.name)}</div><div><b>Admission:</b> ${esc(d.student.admissionNo)}</div><div><b>Class:</b> ${esc(d.class?.name||className(d.student.classId))}</div><div><b>Session:</b> ${esc(d.school.session)}</div><div><b>Term:</b> ${esc(d.school.term)}</div><div><b>Parent:</b> ${esc(d.parent?.name||"—")}</div></div>${resultTable(d.results.map(r=>({...r,student:"",subject:subjectName(r.subjectId)})))}<h4>Attendance</h4><p>${attRate(d.attendance)}% recorded attendance (${d.attendance.length} records).</p><h4>Teacher / Principal remarks</h4><p class="muted">Academic remarks can be entered through the results workflow.</p></div>`}
function logout(){localStorage.removeItem("masabaToken");localStorage.removeItem("masabaUser");location.hash="home";toast("Signed out");render()}
function attachTabHandlers(t){
 if(t==="Attendance"&&getUser().role==="teacher")$("#attendanceForm")?.addEventListener("submit",async e=>{e.preventDefault();const date=$("#attDate").value;try{for(const s of e.target.querySelectorAll("select[data-student]"))await api("/api/attendance",{method:"POST",body:JSON.stringify({studentId:s.dataset.student,date,status:s.value})});toast("Attendance saved");openTab("Attendance")}catch(err){toast(err.message)}});
 if(t==="Settings")$("#settingsForm")?.addEventListener("submit",async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.emails=b.emails.split(",").map(x=>x.trim()).filter(Boolean);b.phones=b.phones.split(",").map(x=>x.trim()).filter(Boolean);try{await api("/api/settings",{method:"PATCH",body:JSON.stringify(b)});toast("Settings updated")}catch(err){toast(err.message)}});
}
function pwFormHtml(title,intro,forced){return `<div class="panel" style="max-width:520px;margin:30px auto"><h3>${title}</h3><p class="muted">${intro}</p><form id="pwForm" class="formGrid"><label class="fullRow">Current password<input name="currentPassword" type="password" required autocomplete="current-password"></label><label class="fullRow">New password (at least 8 characters)<input name="newPassword" type="password" minlength="8" required autocomplete="new-password"></label><label class="fullRow">Confirm new password<input name="confirm" type="password" minlength="8" required autocomplete="new-password"></label><button class="btn primary fullRow">Save new password</button>${forced?`<button type="button" class="btn ghost fullRow" onclick="logout()">Sign out</button>`:""}</form></div>`}
function bindPwForm(after){$("#pwForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());if(b.newPassword!==b.confirm)return toast("The new passwords do not match");try{const d=await api("/api/auth/change-password",{method:"POST",body:JSON.stringify({currentPassword:b.currentPassword,newPassword:b.newPassword})});localStorage.setItem("masabaToken",d.token);localStorage.setItem("masabaUser",JSON.stringify(d.user));toast("Password changed");after()}catch(err){toast(err.message)}}}
function forcePasswordChange(){app.innerHTML=`<section class="section page">${pwFormHtml("Set your own password","For security, please replace the temporary password you were given before you continue.",true)}</section>`;bindPwForm(()=>renderPortal())}
function changePasswordForm(){$("#dashContent").innerHTML=pwFormHtml("Change password","",false);bindPwForm(()=>openTab("Overview"))}
function genPw(){const c="abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789";return Array.from(crypto.getRandomValues(new Uint32Array(10)),n=>c[n%c.length]).join("")}
async function tabUsers(){const [users,teachers,students,parents]=await Promise.all([api("/api/users"),api("/api/teachers"),api("/api/students"),api("/api/parents")]);window._userPeople={teacher:teachers,student:students,parent:parents};const me=getUser();return `<div class="panel"><div class="toolbar"><button class="btn primary" onclick="userForm()">+ Create login</button><button class="btn ghost" onclick="downloadBackup()">Download backup</button></div><p class="muted">Every person needs a login before they can sign in. You give them a temporary password and they must replace it the first time they sign in.</p><div class="tableWrap"><table class="table"><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th></th></tr>${users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>${esc(u.owner?"Proprietor":roleLabel(u.role))}</td><td>${u.active===false?"Disabled":(u.mustChange?"Waiting for first login":"Active")}</td><td>${(u.id===me.id||u.owner||(!me.owner&&["admin","principal"].includes(u.role)))?"":`<button class="btn ghost" onclick="resetUser('${u.id}')">Reset password</button> <button class="btn ghost" onclick="toggleUser('${u.id}',${u.active===false})">${u.active===false?"Enable":"Disable"}</button>`}</td></tr>`).join("")}</table></div></div>`}
function userForm(){const me=getUser(),rl=me.owner?["admin","principal","teacher","student","parent"]:["teacher","student","parent"];$("#dashContent").innerHTML=`<div class="panel"><div class="toolbar"><button class="btn ghost" onclick="openTab('Users')">← Back</button></div><h3>Create login</h3><form id="userForm" class="formGrid"><label>Account type<select name="role" id="ufRole">${rl.map(r=>`<option value="${r}">${esc(roleLabel(r))}</option>`).join("")}</select></label><label id="ufPersonWrap">Person<select name="personId" id="ufPerson"></select></label><label id="ufNameWrap">Full name<input name="name" id="ufName"></label><label>Username<input name="username" id="ufUser" required></label><label>Temporary password<input name="password" id="ufPass" value="${genPw()}" required minlength="8"></label><button class="btn primary fullRow">Create login</button></form></div>`;
const fill=()=>{const r=$("#ufRole").value,id=$("#ufPerson").value,p=(window._userPeople[r]||[]).find(x=>x.id===id);if(p){const v=(r==="parent"?String(p.phone||"").replace(/\s+/g,""):r==="student"?(p.admissionNo||""):(p.staffId||""));if(v)$("#ufUser").value=v}};
const sync=()=>{const r=$("#ufRole").value,needs=["teacher","student","parent"].includes(r);$("#ufPersonWrap").style.display=needs?"":"none";$("#ufNameWrap").style.display=needs?"none":"";const list=needs?(window._userPeople[r]||[]):[];$("#ufPerson").innerHTML=list.length?list.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join(""):`<option value="">No ${r}s added yet - add them first</option>`;fill()};
$("#ufRole").onchange=sync;$("#ufPerson").onchange=fill;sync();
$("#userForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());try{const u=await api("/api/users",{method:"POST",body:JSON.stringify(b)});showCredentials(u.username,b.password,u.name)}catch(err){toast(err.message)}}}
function showCredentials(u,p,name){$("#dashContent").innerHTML=`<div class="panel"><h3>Login ready for ${esc(name)}</h3><p class="muted">Write these down or send them to the person now. The password cannot be shown again, but you can reset it at any time.</p><div class="listItem"><b>Username:</b> ${esc(u)}<br><b>Temporary password:</b> ${esc(p)}</div><p class="muted">They will be asked to choose their own password when they first sign in.</p><div class="toolbar"><button class="btn primary" onclick="openTab('Users')">Done</button></div></div>`}
async function resetUser(id){if(!confirm("Reset this person's password? A new temporary password will be created."))return;const pw=genPw();try{const u=await api("/api/users/"+id,{method:"PATCH",body:JSON.stringify({newPassword:pw})});showCredentials(u.username,pw,u.name)}catch(e){toast(e.message)}}
async function toggleUser(id,enable){try{await api("/api/users/"+id,{method:"PATCH",body:JSON.stringify({active:enable})});toast(enable?"Account enabled":"Account disabled");openTab("Users")}catch(e){toast(e.message)}}
async function downloadBackup(){try{const r=await fetch("/api/backup",{headers:{Authorization:"Bearer "+getToken()}});if(!r.ok)throw new Error("Backup failed");const b=await r.blob(),a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="masaba-backup-"+new Date().toISOString().slice(0,10)+".json";a.click();toast("Backup downloaded")}catch(e){toast(e.message)}}
/* ================= Stage 2 + 3 screens ================= */
const isMgmt=()=>["admin","principal"].includes(getUser()?.role);
const isStaff=()=>["admin","principal","teacher"].includes(getUser()?.role);
const todayStr=()=>new Date().toISOString().slice(0,10);
const waLink=(phone,text)=>{let d=String(phone||"").replace(/\D/g,"");if(!d)return"";if(d.startsWith("0"))d="234"+d.slice(1);return "https://wa.me/"+d+"?text="+encodeURIComponent(text)};
const isActiveStu=s=>!s.status||s.status==="Active"||s.status==="Inactive";
const statusPill=s=>`<span class="pill ${s&&s!=="Active"&&s!=="Inactive"?"pillWarn":""}">${esc(s||"Active")}</span>`;
const backBtn=(tab)=>`<div class="toolbar"><button class="btn ghost" onclick="openTab('${tab}')">← Back</button></div>`;

/* ---------- images ---------- */
function compressImage(file,max=1280,q=.78){return new Promise((res,rej)=>{if(!/^image\//.test(file.type)||file.type==="image/gif")return res(file);const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{let w=img.width,h=img.height;const k=Math.min(1,max/Math.max(w,h));w=Math.round(w*k);h=Math.round(h*k);const c=document.createElement("canvas");c.width=w;c.height=h;c.getContext("2d").drawImage(img,0,0,w,h);c.toBlob(b=>{URL.revokeObjectURL(url);b?res(new File([b],file.name.replace(/\.\w+$/,"")+".jpg",{type:"image/jpeg"})):res(file)},"image/jpeg",q)};img.onerror=()=>{URL.revokeObjectURL(url);rej(new Error("Could not read "+file.name))};img.src=url})}
async function uploadFile(file){const f=await compressImage(file);if(f.size>4*1024*1024)throw new Error(file.name+" is too large (maximum 4 MB)");const fd=new FormData();fd.append("file",f);return (await api("/api/upload",{method:"POST",body:fd})).url}
function openLightbox(url){const d=document.createElement("div");d.className="lightbox";d.innerHTML=`<img src="${esc(url)}" alt="">`;d.onclick=()=>d.remove();document.body.appendChild(d)}

/* ---------- students: expel / withdraw / reinstate ---------- */
async function tabStudents(){const u=getUser(),rows=await api("/api/students?all=1");window._students=rows;if(isMgmt())window._parents=await api("/api/parents");const cur=rows.filter(isActiveStu),removed=rows.length-cur.length,list=window._showRemoved?rows:cur;
return `<div class="panel"><div class="toolbar">${isMgmt()?`<button class="btn primary" onclick="studentForm()">+ Add student</button>`:""}<button class="btn ghost" onclick="loadAll().then(()=>openTab('Students'))">Refresh</button><label class="check"><input type="checkbox" ${window._showRemoved?"checked":""} onchange="window._showRemoved=this.checked;openTab('Students')"> Show expelled / withdrawn (${removed})</label></div><div class="tableWrap"><table class="table"><tr><th>Admission</th><th>Name</th><th>Class</th><th>Subjects</th><th>Parent</th><th>Status</th><th>Action</th></tr>${list.map(s=>`<tr><td>${esc(s.admissionNo)}</td><td><b>${esc(s.name)}</b>${s.statusReason?`<small class="mini">${esc(s.statusReason)} (${esc(s.statusDate||"")})</small>`:""}</td><td>${esc(className(s.classId))}</td><td>${(s.subjectIds||[]).length}</td><td>${esc(window._parents?.find(p=>p.id===s.parentId)?.name||s.parentId||"—")}</td><td>${statusPill(s.status)}</td><td><div class="actionsRow">${isActiveStu(s)?`${isMgmt()?`<button class="btn ghost" onclick="studentForm('${s.id}')">Edit</button>`:""}<button class="btn ghost" onclick="subjectManager('${s.id}')">Subjects</button><button class="btn ghost" onclick="viewReport('${s.id}')">Report</button><button class="danger" onclick="removeStudentForm('${s.id}')">Remove</button>`:`<button class="btn ghost" onclick="viewReport('${s.id}')">Report</button>${isMgmt()?`<button class="btn primary" onclick="reinstateStudent('${s.id}')">Reinstate</button>`:""}`}</div></td></tr>`).join("")}</table></div></div>`}
function removeStudentForm(id){const s=(window._students||[]).find(x=>x.id===id);if(!s)return;$("#dashContent").innerHTML=`<div class="panel">${backBtn("Students")}<h3>Remove ${esc(s.name)} from the school</h3><p class="muted">Their results, fees and history stay saved. They disappear from class lists, attendance and fee forms, and their login is switched off. The principal or administrator can reinstate them later.</p><form id="removeForm" class="formGrid"><label>Reason type<select name="status"><option value="Expelled">Expelled</option><option value="Withdrawn">Withdrawn / no longer coming to school</option></select></label><label class="fullRow">Reason (short)<input name="reason" required minlength="3" maxlength="300" placeholder="For example: moved to another school"></label><button class="btn primary fullRow" style="background:#b42318">Remove student</button></form></div>`;$("#removeForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());if(!confirm("Remove "+s.name+" from the school?"))return;try{await api("/api/students/"+id+"/status",{method:"POST",body:JSON.stringify(b)});toast("Student removed");openTab("Students")}catch(err){toast(err.message)}}}
async function reinstateStudent(id){if(!confirm("Reinstate this student? Their login will be switched back on."))return;try{await api("/api/students/"+id+"/status",{method:"POST",body:JSON.stringify({status:"Active"})});toast("Student reinstated");openTab("Students")}catch(e){toast(e.message)}}

/* ---------- bank accounts ---------- */
const BANKS=["Access Bank","Citibank","Ecobank","Fidelity Bank","First Bank","FCMB","Globus Bank","GTBank","Heritage Bank","Keystone Bank","Kuda","Moniepoint","OPay","PalmPay","Polaris Bank","Providus Bank","Stanbic IBTC","Standard Chartered","Sterling Bank","SunTrust","Union Bank","UBA","Unity Bank","Wema Bank","Zenith Bank"];
const bankCard=(b,manage)=>`<div class="listItem"><span><b>${esc(b.bankName)}</b><br><span class="acctNo">${esc(b.accountNumber)}</span> <button class="btn ghost" onclick="navigator.clipboard&&navigator.clipboard.writeText('${esc(b.accountNumber)}').then(()=>toast('Account number copied'))">Copy</button><small class="mini">${esc(b.accountName)}${b.note?" · "+esc(b.note):""}</small><small class="mini">Last updated by ${esc(b.updatedBy||"—")} on ${esc((b.updatedAt||"").slice(0,10))}</small></span>${manage?`<span class="actionsRow"><button class="btn ghost" onclick="bankForm('${b.id}')">Edit</button>${isMgmt()?`<button class="danger" onclick="deleteBank('${b.id}')">Delete</button>`:""}</span>`:""}</div>`;
async function tabBank(){const rows=await api("/api/bank");window._bank=rows;let notify="";if(isMgmt()){const s=await api("/api/settings");notify=`<div class="panel"><h4>Alert email</h4><p class="muted mini">This address gets an email whenever a parent submits a payment and whenever bank details are changed.</p><form id="notifyForm" class="formGrid"><label class="fullRow">Email<input name="notifyEmail" type="email" value="${esc(s.notifyEmail||"")}"></label><button class="btn ghost fullRow">Save alert email</button></form></div>`}
return `<div class="panel"><div class="toolbar"><button class="btn primary" onclick="bankForm()">+ Add account</button></div><p class="muted">These are the school accounts parents are told to pay into. Every change is recorded in the audit log and shown below with who made it.</p>${rows.map(b=>bankCard(b,true)).join("")||"<div class='empty'>No bank account added yet.</div>"}</div>${notify}`}
function bankForm(id){const b=(window._bank||[]).find(x=>x.id===id)||{bankName:"",accountName:"",accountNumber:"",note:""};$("#dashContent").innerHTML=`<div class="panel">${backBtn("Bank")}<h3>${id?"Edit":"Add"} bank account</h3><form id="bankForm" class="formGrid"><label>Bank<input name="bankName" list="bankList" value="${esc(b.bankName)}" required><datalist id="bankList">${BANKS.map(x=>`<option value="${x}">`).join("")}</datalist></label><label>Account name<input name="accountName" value="${esc(b.accountName)}" required></label><label>Account number (10 digits)<input name="accountNumber" inputmode="numeric" maxlength="10" value="${esc(b.accountNumber)}" required></label><label>Note (optional)<input name="note" value="${esc(b.note)}" placeholder="For example: Tuition fees"></label><button class="btn primary fullRow">Save account</button></form></div>`;$("#bankForm").onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target).entries());try{await api(id?"/api/bank/"+id:"/api/bank",{method:id?"PATCH":"POST",body:JSON.stringify(v)});toast("Bank account saved");openTab("Bank")}catch(err){toast(err.message)}}}
async function deleteBank(id){if(!confirm("Delete this bank account?"))return;try{await api("/api/bank/"+id,{method:"DELETE"});toast("Deleted");openTab("Bank")}catch(e){toast(e.message)}}

/* ---------- fees and payments ---------- */
async function tabFees(){const u=getUser(),fees=await api("/api/fees"),bank=await api("/api/bank");window._bank=bank;
if(isMgmt()){const [studs,parents,pays]=await Promise.all([api("/api/students?all=1"),api("/api/parents"),api("/api/payments")]);window._students=studs;const pend=pays.filter(p=>p.status==="Pending").length;
const acctText=bank.map(b=>`${b.bankName} ${b.accountNumber} (${b.accountName})`).join("; ");
return `<div class="panel"><div class="toolbar"><button class="btn primary" onclick="feeForm()">+ Add fee record</button>${pend?`<button class="btn ghost" onclick="openTab('Payments')">💳 ${pend} payment(s) waiting for confirmation</button>`:""}</div><div class="tableWrap"><table class="table"><tr><th>Student</th><th>Item</th><th>Amount</th><th>Paid</th><th>Balance</th><th>Status</th><th></th></tr>${fees.map(f=>{const st=studs.find(s=>s.id===f.studentId),par=parents.find(p=>p.id===st?.parentId),bal=Number(f.amount)-Number(f.paid||0),msg=`Dear ${par?.name||"Parent"}, this is a reminder from ${st?"Masaba International Schools":"the school"}: ${st?.name||"your child"}'s ${f.item} balance of ${fmtMoney(bal)} is outstanding. Please pay by bank transfer to ${acctText||"the school account"} and upload your proof of payment in the parent portal. Thank you.`,wa=bal>0&&par?.phone?waLink(par.phone,msg):"";return `<tr><td>${esc(st?.name||f.studentId)}</td><td>${esc(f.item)}</td><td>${fmtMoney(f.amount)}</td><td>${fmtMoney(f.paid)}</td><td>${fmtMoney(bal)}</td><td><span class="pill">${esc(f.status)}</span></td><td><div class="actionsRow">${bal>0?`<button class="btn ghost" onclick="recordPaymentForm('${f.id}')">+ Payment</button>`:""}${wa?`<a class="btn ghost" target="_blank" rel="noopener" href="${wa}">WhatsApp reminder</a>`:""}</div></td></tr>`}).join("")}</table></div></div>`}
const pays=await api("/api/payments"),kids=(dashData?.children)||(dashData?.student?[dashData.student]:[]);window._students=kids;
return `<div class="panel"><h3>How to pay</h3><p class="muted">Pay by bank transfer to one of these accounts, then tap <b>I have paid</b> on the fee and upload your proof. The school will confirm and you will get a receipt.</p>${bank.map(b=>bankCard(b,false)).join("")||"<div class='empty'>The school has not added a bank account yet. Please contact the office.</div>"}</div><div class="panel"><h3>Fees</h3><div class="tableWrap"><table class="table"><tr><th>Student</th><th>Item</th><th>Amount</th><th>Paid</th><th>Balance</th><th>Status</th><th></th></tr>${fees.map(f=>{const bal=Number(f.amount)-Number(f.paid||0),pend=pays.some(p=>p.feeId===f.id&&p.status==="Pending");return `<tr><td>${esc(kids.find(s=>s.id===f.studentId)?.name||f.studentId)}</td><td>${esc(f.item)}</td><td>${fmtMoney(f.amount)}</td><td>${fmtMoney(f.paid)}</td><td>${fmtMoney(bal)}</td><td><span class="pill">${esc(f.status)}</span></td><td>${u.role==="parent"&&bal>0?(pend?`<span class="muted mini">Waiting for confirmation</span>`:`<button class="btn primary" onclick="payFeeForm('${f.id}')">I have paid</button>`):""}</td></tr>`}).join("")}</table></div></div><div class="panel"><h3>Payment history</h3>${pays.length?`<div class="tableWrap"><table class="table"><tr><th>Date</th><th>Student</th><th>Amount</th><th>Status</th><th></th></tr>${pays.map(p=>`<tr><td>${esc(p.paidOn)}</td><td>${esc(kids.find(s=>s.id===p.studentId)?.name||"")}</td><td>${fmtMoney(p.amount)}</td><td><span class="pill ${p.status==="Rejected"?"pillWarn":""}">${esc(p.status)}</span>${p.rejectReason?`<small class="mini">${esc(p.rejectReason)}</small>`:""}</td><td>${p.status==="Confirmed"?`<button class="btn ghost" onclick="viewReceipt('${p.id}')">Receipt</button>`:""}</td></tr>`).join("")}</table></div>`:"<div class='empty'>No payments yet.</div>"}</div>`}
async function feeForm(){const students=await api("/api/students");$("#dashContent").innerHTML=`<div class="panel">${backBtn("Fees")}<h3>Add fee record</h3><form id="feeForm" class="formGrid"><label>Student<select name="studentId">${students.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join("")}</select></label><label>Item<input name="item" value="School fees"></label><label>Amount<input name="amount" type="number" min="0"></label><label>Already paid<input name="paid" type="number" min="0" value="0"></label><label>Due date<input name="dueDate" type="date"></label><button class="btn primary fullRow">Save fee</button></form></div>`;$("#feeForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());try{await api("/api/fees",{method:"POST",body:JSON.stringify(b)});toast("Fee record saved");openTab("Fees")}catch(err){toast(err.message)}}}
async function payFeeForm(feeId){const fees=await api("/api/fees"),f=fees.find(x=>x.id===feeId),bank=await api("/api/bank");if(!f)return;const bal=Number(f.amount)-Number(f.paid||0),kid=(window._students||[]).find(s=>s.id===f.studentId);
$("#dashContent").innerHTML=`<div class="panel">${backBtn("Fees")}<h3>I have paid</h3><p class="muted">${esc(kid?.name||"")} · ${esc(f.item)} · balance ${fmtMoney(bal)}</p>${bank.map(b=>bankCard(b,false)).join("")}<form id="payForm" class="formGrid"><label>Amount you paid (₦)<input name="amount" type="number" min="1" max="${bal}" value="${bal}" required></label><label>Date you paid<input name="paidOn" type="date" value="${todayStr()}" required></label><label>Name on the sending account<input name="senderName" required></label><label>Transfer reference (optional)<input name="reference"></label><label class="fullRow">Proof of payment (photo or PDF)<input type="file" id="payProof" accept="image/*,application/pdf"></label><label class="fullRow">Note (optional)<input name="note"></label><button class="btn primary fullRow" id="payBtn">Submit payment</button></form></div>`;
$("#payForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.feeId=feeId;const btn=$("#payBtn");btn.disabled=true;btn.textContent="Submitting...";try{const file=$("#payProof").files[0];if(file)b.proofUrl=await uploadFile(file);await api("/api/payments",{method:"POST",body:JSON.stringify(b)});toast("Submitted. The school will confirm it.");openTab("Fees")}catch(err){toast(err.message);btn.disabled=false;btn.textContent="Submit payment"}}}
async function recordPaymentForm(feeId){const fees=await api("/api/fees"),f=fees.find(x=>x.id===feeId),bal=Number(f.amount)-Number(f.paid||0),st=(window._students||[]).find(s=>s.id===f.studentId);
$("#dashContent").innerHTML=`<div class="panel">${backBtn("Fees")}<h3>Record a payment received</h3><p class="muted">${esc(st?.name||"")} · ${esc(f.item)} · balance ${fmtMoney(bal)}</p><form id="recForm" class="formGrid"><label>Amount received (₦)<input name="amount" type="number" min="1" max="${bal}" value="${bal}" required></label><label>Date<input name="paidOn" type="date" value="${todayStr()}" required></label><label>Sender name<input name="senderName"></label><label>Reference<input name="reference"></label><button class="btn primary fullRow">Record and issue receipt</button></form></div>`;
$("#recForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());b.feeId=feeId;try{const p=await api("/api/payments",{method:"POST",body:JSON.stringify(b)});toast("Payment recorded");viewReceipt(p.id,"Fees")}catch(err){toast(err.message)}}}
async function tabPayments(){const [pays,studs]=await Promise.all([api("/api/payments"),api("/api/students?all=1")]);window._students=studs;const nm=id=>studs.find(s=>s.id===id)?.name||id,pend=pays.filter(p=>p.status==="Pending"),done=pays.filter(p=>p.status!=="Pending");
return `<div class="panel"><h3>Waiting for confirmation (${pend.length})</h3><p class="muted mini">Check your bank account first. Confirm only money that has actually arrived.</p>${pend.map(p=>`<div class="listItem"><span><b>${esc(nm(p.studentId))}</b> · ${fmtMoney(p.amount)}<small class="mini">Paid ${esc(p.paidOn)} by ${esc(p.senderName||p.submittedByName)}${p.reference?" · ref "+esc(p.reference):""}${p.note?" · "+esc(p.note):""}</small>${p.proofUrl?`<a href="${esc(p.proofUrl)}" target="_blank" rel="noopener">View proof</a>`:`<small class="mini">No proof uploaded</small>`}</span><span class="actionsRow"><button class="btn primary" onclick="confirmPayment('${p.id}')">Confirm</button><button class="danger" onclick="rejectPayment('${p.id}')">Reject</button></span></div>`).join("")||"<div class='empty'>Nothing waiting.</div>"}</div><div class="panel"><h3>History</h3>${done.length?`<div class="tableWrap"><table class="table"><tr><th>Date</th><th>Student</th><th>Amount</th><th>Status</th><th>Receipt</th></tr>${done.map(p=>`<tr><td>${esc(p.paidOn)}</td><td>${esc(nm(p.studentId))}</td><td>${fmtMoney(p.amount)}</td><td><span class="pill ${p.status==="Rejected"?"pillWarn":""}">${esc(p.status)}</span>${p.rejectReason?`<small class="mini">${esc(p.rejectReason)}</small>`:""}</td><td>${p.status==="Confirmed"?`<button class="btn ghost" onclick="viewReceipt('${p.id}','Payments')">${esc(p.receiptNo)}</button>`:""}</td></tr>`).join("")}</table></div>`:"<div class='empty'>No history yet.</div>"}</div>`}
async function confirmPayment(id){if(!confirm("Confirm this payment? Do this only after the money is in the school account."))return;try{const p=await api("/api/payments/"+id+"/confirm",{method:"POST",body:"{}"});toast("Confirmed. Receipt "+p.receiptNo);openTab("Payments")}catch(e){toast(e.message)}}
async function rejectPayment(id){const reason=prompt("Why is this payment being rejected? (the parent will see this)");if(!reason)return;try{await api("/api/payments/"+id+"/reject",{method:"POST",body:JSON.stringify({reason})});toast("Payment rejected");openTab("Payments")}catch(e){toast(e.message)}}
async function viewReceipt(id,back="Fees"){try{const d=await api("/api/receipt/"+id),p=d.payment;$("#dashContent").innerHTML=`<div class="reportPrint toolbar"><button class="btn ghost" onclick="openTab('${back}')">← Back</button><button class="btn primary" onclick="window.print()">Print / Save PDF</button></div><div class="report"><div class="reportHead"><img class="reportLogo" src="/assets/logo.jpg"><h2>${esc(d.school.schoolName)}</h2><p class="muted">${esc(d.school.address)}</p><h3>PAYMENT RECEIPT</h3></div><div class="reportMeta"><div><b>Receipt no:</b> ${esc(p.receiptNo)}</div><div><b>Date paid:</b> ${esc(p.paidOn)}</div><div><b>Student:</b> ${esc(d.student?.name||"")}</div><div><b>Class:</b> ${esc(d.class?.name||"")}</div><div><b>Paid by:</b> ${esc(p.senderName||p.submittedByName||"—")}</div><div><b>Method:</b> ${esc(p.method)}</div></div><table class="table"><tr><th>Item</th><th>Session / term</th><th>Amount paid</th></tr><tr><td>${esc(d.fee?.item||"")}</td><td>${esc(d.fee?.session||"")} · ${esc(d.fee?.term||"")}</td><td><b>${fmtMoney(p.amount)}</b></td></tr></table><p><b>Outstanding balance on this item:</b> ${fmtMoney(d.balance)}</p><p class="muted mini">Confirmed by ${esc(p.reviewedBy||"the school office")} on ${esc((p.reviewedAt||"").slice(0,10))}. Thank you.</p></div>`}catch(e){toast(e.message)}}

/* ---------- timetable ---------- */
const DAYS=["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
function ttCanEdit(classId){const u=getUser();return isMgmt()||(u.role==="teacher"&&(dashData?.teacher?.classIds||[]).includes(classId))}
async function tabTimetable(){const u=getUser(),[rows,classes]=await Promise.all([api("/api/timetable"),api("/api/classes")]);window._classes=classes;window._tt=rows;
let list=classes;if(u.role==="student")list=classes.filter(c=>c.id===dashData?.student?.classId);if(u.role==="parent"){const ids=[...new Set((dashData?.children||[]).map(s=>s.classId))];list=classes.filter(c=>ids.includes(c.id))}
if(u.role==="teacher"){const mine=dashData?.teacher?.classIds||[];list=[...classes.filter(c=>mine.includes(c.id)),...classes.filter(c=>!mine.includes(c.id))]}
if(!list.length)return `<div class="panel"><div class="empty">No class found.</div></div>`;if(!list.some(c=>c.id===window._ttClass))window._ttClass=list[0].id;const cid=window._ttClass,mine=rows.filter(r=>r.classId===cid),edit=ttCanEdit(cid);
return `<div class="panel"><div class="toolbar"><label>Class<select onchange="window._ttClass=this.value;openTab('Timetable')">${list.map(c=>`<option value="${c.id}" ${c.id===cid?"selected":""}>${esc(c.name)}</option>`).join("")}</select></label>${edit?`<button class="btn primary" onclick="ttForm()">+ Add lesson</button>`:""}${u.role==="teacher"&&!edit?`<span class="muted mini">You can view this class but only edit your own classes.</span>`:""}</div>${DAYS.map(d=>{const day=mine.filter(r=>r.day===d).sort((a,b)=>a.start.localeCompare(b.start));if(!day.length&&d==="Saturday")return"";return `<div class="ttDay"><h4>${d}</h4>${day.map(r=>`<div class="listItem"><span><b>${esc(r.start)} - ${esc(r.end)}</b> · ${esc(r.subjectName||r.title||"")}${r.subjectName&&r.title?" ("+esc(r.title)+")":""}<small class="mini">${esc(r.teacherName||"")}${r.room?" · Room "+esc(r.room):""}</small></span>${edit?`<span class="actionsRow"><button class="btn ghost" onclick="ttForm('${r.id}')">Edit</button><button class="danger" onclick="ttDelete('${r.id}')">Delete</button></span>`:""}</div>`).join("")||"<div class='empty'>No lessons.</div>"}</div>`}).join("")}</div>`}
async function ttForm(id){const r=(window._tt||[]).find(x=>x.id===id)||{classId:window._ttClass,day:"Monday",start:"08:00",end:"08:40",subjectId:"",title:"",teacherId:"",room:""};const [subs,teachers]=await Promise.all([api("/api/subjects"),api("/api/teachers")]);const u=getUser(),myClasses=isMgmt()?window._classes:window._classes.filter(c=>(dashData?.teacher?.classIds||[]).includes(c.id));
$("#dashContent").innerHTML=`<div class="panel">${backBtn("Timetable")}<h3>${id?"Edit":"Add"} lesson</h3><form id="ttForm" class="formGrid"><label>Class<select name="classId">${myClasses.map(c=>`<option value="${c.id}" ${r.classId===c.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select></label><label>Day<select name="day">${DAYS.map(d=>`<option ${r.day===d?"selected":""}>${d}</option>`).join("")}</select></label><label>Starts<input name="start" type="time" value="${esc(r.start)}" required></label><label>Ends<input name="end" type="time" value="${esc(r.end)}" required></label><label>Subject<select name="subjectId"><option value="">— none (use title) —</option>${subs.filter(s=>s.active!==false).map(s=>`<option value="${s.id}" ${r.subjectId===s.id?"selected":""}>${esc(s.name)}</option>`).join("")}</select></label><label>Title (for Break, Assembly...)<input name="title" value="${esc(r.title)}"></label><label>Teacher<select name="teacherId"><option value="">— none —</option>${teachers.map(t=>`<option value="${t.id}" ${r.teacherId===t.id?"selected":""}>${esc(t.name)}</option>`).join("")}</select></label><label>Room (optional)<input name="room" value="${esc(r.room)}"></label><button class="btn primary fullRow">Save lesson</button></form></div>`;
$("#ttForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());try{await api(id?"/api/timetable/"+id:"/api/timetable",{method:id?"PATCH":"POST",body:JSON.stringify(b)});window._ttClass=b.classId;toast("Lesson saved");openTab("Timetable")}catch(err){toast(err.message)}}}
async function ttDelete(id){if(!confirm("Delete this lesson?"))return;try{await api("/api/timetable/"+id,{method:"DELETE"});toast("Deleted");openTab("Timetable")}catch(e){toast(e.message)}}

/* ---------- gallery (post style) ---------- */
const timeAgoText=iso=>{const d=new Date(iso);return isNaN(d)?"":d.toLocaleDateString(undefined,{day:"numeric",month:"short",year:"numeric"})};
function postHtml(p,manage){const n=p.photos.length,cls=n===1?"one":n<=4?"two":"three";const canDel=manage&&(isMgmt()||p.authorId===getUser().id);
return `<article class="postCard"><div class="postHead"><span class="avatar">${esc((p.authorName||"?").charAt(0).toUpperCase())}</span><span><b>${esc(p.authorName)}</b><small class="mini">${esc(timeAgoText(p.createdAt))}${p.album?" · "+esc(p.album):""}</small></span>${p.status==="pending"?`<span class="pill pillWarn">Awaiting approval</span>`:""}</div>${p.caption?`<p class="postCaption">${esc(p.caption)}</p>`:""}<div class="photoGrid ${cls}">${p.photos.map(u=>`<img loading="lazy" src="${esc(u)}" alt="" onclick="openLightbox('${esc(u)}')">`).join("")}</div>${manage?`<div class="actionsRow postActions">${p.status==="pending"&&isMgmt()?`<button class="btn primary" onclick="approvePost('${p.id}')">Approve</button>`:""}${(isMgmt()||p.authorId===getUser().id)?`<button class="btn ghost" onclick="editPost('${p.id}')">Edit caption</button>`:""}${canDel?`<button class="danger" onclick="deletePost('${p.id}')">Delete</button>`:""}</div>`:""}</article>`}
async function tabGallery(){const posts=await api("/api/gallery");window._posts=posts;let toggle="";if(isMgmt()){const s=await api("/api/settings");toggle=`<label class="check"><input type="checkbox" ${s.galleryApproval?"checked":""} onchange="setGalleryApproval(this.checked)"> Teachers' posts need my approval before they show on the website</label>`}
const albums=[...new Set(posts.map(p=>p.album).filter(Boolean))];
return `<div class="panel composer"><h3>Create a post</h3><textarea id="gCaption" rows="3" maxlength="1000" placeholder="What happened? Write a caption..."></textarea><input id="gAlbum" list="albumList" placeholder="Album or event (optional)"><datalist id="albumList">${albums.map(a=>`<option value="${esc(a)}">`).join("")}</datalist><input type="file" id="gFiles" accept="image/*" multiple onchange="previewFiles(this)"><div id="gPreview" class="photoGrid three"></div><div class="toolbar"><button class="btn primary" id="gPost" onclick="submitPost()">Post</button><span class="muted mini">Up to 10 photos. They are shrunk automatically so they load fast.</span></div>${toggle}</div>${posts.map(p=>postHtml(p,true)).join("")||"<div class='empty'>No posts yet. Share the first school moment above.</div>"}`}
async function setGalleryApproval(v){try{await api("/api/settings",{method:"PATCH",body:JSON.stringify({galleryApproval:!!v})});toast(v?"Teacher posts now need approval":"Teacher posts publish immediately")}catch(e){toast(e.message)}}
async function submitPost(){const files=[...$("#gFiles").files].slice(0,10);if(!files.length)return toast("Choose at least one photo");const btn=$("#gPost");btn.disabled=true;try{const urls=[];for(let i=0;i<files.length;i++){btn.textContent=`Uploading ${i+1} of ${files.length}...`;urls.push(await uploadFile(files[i]))}btn.textContent="Posting...";const p=await api("/api/gallery",{method:"POST",body:JSON.stringify({caption:$("#gCaption").value,album:$("#gAlbum").value,photos:urls})});toast(p.status==="pending"?"Posted. It will show on the website after approval.":"Posted to the gallery");openTab("Gallery")}catch(e){toast(e.message);btn.disabled=false;btn.textContent="Post"}}
async function editPost(id){const p=(window._posts||[]).find(x=>x.id===id);const c=prompt("Edit caption",p?.caption||"");if(c===null)return;try{await api("/api/gallery/"+id,{method:"PATCH",body:JSON.stringify({caption:c})});toast("Updated");openTab("Gallery")}catch(e){toast(e.message)}}
async function approvePost(id){try{await api("/api/gallery/"+id,{method:"PATCH",body:JSON.stringify({status:"published"})});toast("Approved");openTab("Gallery")}catch(e){toast(e.message)}}
async function deletePost(id){if(!confirm("Delete this post and its photos?"))return;try{await api("/api/gallery/"+id,{method:"DELETE"});toast("Deleted");openTab("Gallery")}catch(e){toast(e.message)}}
async function galleryPage(){document.body.classList.remove("portalMode");const posts=await api("/api/public/gallery");return `<section class="section page">${sectionHead("GALLERY","A window into school life.","Moments from our classrooms, events and activities.")}<div class="feed">${posts.map(p=>postHtml(p,false)).join("")||"<div class='empty'>Photos will appear here soon.</div>"}</div></section>`}

function previewFiles(inp){$("#gPreview").innerHTML=[...inp.files].slice(0,10).map(f=>`<img src="${URL.createObjectURL(f)}" alt="">`).join("")}
/* ================= Final build: public pages, messages, class teachers ================= */
async function publicData(){const d=await api("/api/public");window._school=d.school;return d}
async function ensurePublic(){if(!window._classes||!window._school){const d=await publicData();window._classes=d.classes;window._subjects=d.subjects}}
const telHref=p=>{let d=String(p||"").replace(/\D/g,"");if(d.startsWith("0"))d="234"+d.slice(1);return "tel:+"+d};
const mapsHref=a=>"https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(a||"");

function home(){const s=window._school||{},hero=s.heroImage||"/assets/hero.jpg";
return `<section class="heroX"><div class="heroText"><span class="eyebrow">KINDERGARTEN • NURSERY • PRIMARY • SECONDARY</span><h1>Illuminating minds & hearts to a <em>brighter future.</em></h1><p class="lead">At Masaba International Schools, children learn Science, Technology, Engineering and Mathematics by doing, from Kindergarten to SSS3, in Abeokuta, Ogun State.</p><div class="actions"><a class="btn primary" href="#admissions">Explore Admissions</a><a class="btn ghost" href="#stem">See our STEM programme</a></div><div class="badges"><span class="badge">✓ WAEC</span><span class="badge">✓ BECE</span><span class="badge">✓ CBT</span></div></div><figure class="heroPhoto"><img src="${esc(hero)}" alt="Students in school uniform gathered around a large model race-track set they are building together" width="1200" height="900" fetchpriority="high"><figcaption>Hands-on learning at Masaba International Schools</figcaption></figure></section>
<div class="stats"><div><b>Kindergarten → SSS3</b><small>Complete school journey</small></div><div><b>100–150+</b><small>Growing student community</small></div><div><b>40+</b><small>Dedicated educators</small></div><div><b>WAEC & BECE</b><small>Exam preparation</small></div></div>
<section class="section">${sectionHead("WHY MASABA INTERNATIONAL SCHOOLS","Education with purpose.","A school where learning is hands-on and families stay connected.")}
<article class="whyFeature"><div><span class="eyebrow">STEM</span><h3>Science, Technology, Engineering and Mathematics, learned by doing.</h3><p class="muted">From “It looks like Play…” in the early years to the BUILD programme in secondary school, children explore, test ideas and solve problems together.</p><a class="btn primary" href="#stem">Explore STEM</a></div><img src="/assets/stem-build.jpg" alt="Small robots and a bridge model on a classroom table" width="1000" height="705" loading="lazy" decoding="async"></article>
<div class="whyGrid"><article class="card"><span class="num">01</span><h3>Strong academics</h3><p class="muted">Support for early years, primary and secondary learners, with WAEC and BECE examination readiness.</p></article><article class="card"><span class="num">02</span><h3>High expectations</h3><p class="muted">Research-based teaching methods that build higher-order thinking and a problem-solving approach.</p></article><article class="card"><span class="num">03</span><h3>Digital learning</h3><p class="muted">Student portals, learning materials, assignments, results and computer-based examinations.</p></article><article class="card"><span class="num">04</span><h3>School community</h3><p class="muted">Parents, teachers, students and administrators stay connected, including direct messages to class teachers.</p></article></div></section>
<section class="missionBand"><div><span class="eyebrow" style="color:var(--lime)">OUR MISSION</span><blockquote>To illuminate and cultivate young minds and hearts towards a brighter future.</blockquote><p class="planting">Planting & Nurturing</p></div><div><h4>How?</h4><ul><li>High expectations</li><li>Unlimited authentic experiences</li><li>Research-based teaching methods</li><li>Higher order thinking</li><li>Problem solving approach</li><li>Motivation and collaboration</li></ul></div></section>
<div class="cta"><div><span class="eyebrow" style="color:var(--lime)">MASABA INTERNATIONAL SCHOOLS DIGITAL CAMPUS</span><h2>Everything the school needs, in one place.</h2><p>Secure portals, school records, CBT, admissions, results, attendance and more.</p></div><a class="btn lime" href="#portal">Open Portal</a></div>`}

function stemPage(){return `<section class="section page"><div class="stemHero"><div><span class="eyebrow">STEM AT MASABA INTERNATIONAL SCHOOLS</span><h1>Science, Technology, Engineering and Mathematics.</h1><p class="lead">Science, Technology, Engineering and Mathematics (STEM) are at the heart of a technological revolution which is transforming the way we live and the way we work. If Nigeria is to be relevant in this transformation, we must be a leader in nurturing, developing and deploying STEM talent. Our education system must play a key role in equipping learners with the knowledge, skills and dispositions to effect these changes.</p></div><img class="stemMark" src="/assets/stem-mark.png" alt="The letters S, T, E and M in four coloured circles beside the outline of a head" width="560" height="560"></div>
<div class="prose"><p>At Masaba International Schools, we encourage every student to participate in Science, Technology, Engineering and Mathematics during their education and training so as to open the doors to exciting and fulfilling jobs, careers and life opportunities.</p><p>The foundations for STEM education begin in early childhood. From their earliest years through their play experiences and environment, children engage with the world in ways that can promote learning related to Science, Technology, Engineering and Mathematics.</p></div>
<div class="programmes"><article class="card"><span class="eyebrow">EARLY YEARS</span><h3>“It looks like Play…”</h3><p class="muted">Our school provides an environment for STEM exploration through hands-on multisensory and creative experiences.</p></article><article class="card"><span class="eyebrow">SECONDARY SCHOOL</span><h3>BUILD</h3><p class="muted"><b>B</b>etter <b>U</b>nderstanding <b>I</b>nvolves <b>L</b>earning and <b>D</b>oing. We extend the hands-on experience into our secondary school through this programme.</p></article></div>
<div class="prose"><p>By engaging in these experiences, young children are developing curiosity, inquisitiveness, critical-thinking, problem-solving capacities, and team building.</p></div>
<div class="photoRow"><img src="/assets/stem-play.jpg" alt="Two young pupils in school uniform playing doctor with a stethoscope" width="1000" height="683" loading="lazy" decoding="async"><img src="/assets/stem-science.jpg" alt="A pupil's hand on an open science book beside a microscope and a magnifying glass" width="395" height="730" loading="lazy" decoding="async"><img src="/assets/stem-build.jpg" alt="Small robots and a bridge model on a classroom table" width="1000" height="705" loading="lazy" decoding="async"></div>
<div class="cta" style="margin-top:34px"><div><span class="eyebrow" style="color:var(--lime)">THE FUTURE STARTS EARLY</span><h2>Give your child a greater chance of making it in life.</h2><p>Prepare him or her for a career of the future.</p></div><a class="btn lime" href="#admissions">Apply now</a></div></section>`}

function staticPage(route){document.body.classList.remove("portalMode");
const structure=`<div class="card"><h3>School structure</h3><div class="list">${(window._classes||[]).map(c=>`<div class="listItem"><span>${esc(c.name)}</span><span class="pill">${esc(c.section)}</span></div>`).join("")}</div></div>`;
if(route==="academics")return `<section class="section page">${sectionHead("ACADEMICS","A complete learning journey.","From early years through senior secondary, the school supports foundational literacy, numeracy, science, technology and examination preparation, including WAEC and BECE.")}<div class="split"><div class="card"><span class="eyebrow">STEM</span><h3>Learning by doing</h3><p class="muted">STEM is part of school life at every level: “It looks like Play…” in the early years and the BUILD programme in secondary school.</p><a class="btn primary" href="#stem">Read about STEM</a></div>${structure}</div></section>`;
return `<section class="section page">${sectionHead("ABOUT MASABA INTERNATIONAL SCHOOLS","A learning community built around purpose, discipline and opportunity.","Masaba International Schools serves learners from Kindergarten through SSS3 in Abeokuta, Ogun State. The school combines strong academics, hands-on STEM learning and a supportive community, and offers a digital campus for students, parents, teachers and administrators.")}<section class="missionBand"><div><span class="eyebrow" style="color:var(--lime)">OUR MISSION</span><blockquote>To illuminate and cultivate young minds and hearts towards a brighter future.</blockquote><p class="planting">Planting & Nurturing</p></div><div><h4>How?</h4><ul><li>High expectations</li><li>Unlimited authentic experiences</li><li>Research-based teaching methods</li><li>Higher order thinking</li><li>Problem solving approach</li><li>Motivation and collaboration</li></ul></div></section><div class="split" style="margin-top:22px">${structure}<div class="card"><h3>Our STEM programme</h3><p class="muted">Children explore Science, Technology, Engineering and Mathematics through hands-on experiences at every level.</p><a class="btn primary" href="#stem">Explore STEM</a></div></div></section>`}

async function admissions(){document.body.classList.remove("portalMode");await ensurePublic();return `<section class="section page">${sectionHead("ADMISSIONS","Begin your journey at Masaba International Schools.","Submit an enquiry and the school will review it and get back to you.")}<div class="card formCard"><form id="admissionForm" class="formGrid"><label>Parent / Guardian name<input name="parentName" required></label><label>Phone number<input name="phone" required></label><label>Email<input name="email" type="email"></label><label>Student name<input name="studentName" required></label><label>Class applying for<select name="classApplying"><option value="">Select class</option>${window._classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join("")}</select></label><label>Previous school (if any)<input name="priorSchool" maxlength="120" placeholder="Leave blank if starting school"></label><label>Last class completed (if any)<input name="priorGrade" maxlength="60" placeholder="For example: Primary 3"></label><label class="fullRow">Message<textarea name="message" placeholder="Anything the school should know?"></textarea></label><button class="btn primary fullRow">Submit admission enquiry</button></form></div></section>`}

/* ---------- contact page with class buttons ---------- */
async function contactPage(){const d=await publicData();window._classes=d.classes;window._subjects=d.subjects;const s=d.school;
return `<section class="section page">${sectionHead("CONTACT","Reach Masaba International Schools.","We are happy to hear from you.")}<div class="contactGrid"><div class="card"><h3>Visit or call</h3><address class="contactList"><a class="contactItem" href="${mapsHref(s.address)}" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 21s7-6.2 7-11.5A7 7 0 0 0 5 9.5C5 14.8 12 21 12 21z"/><circle cx="12" cy="9.5" r="2.5"/></svg><span>${esc(s.address)}</span></a>${(s.emails||[]).map(e=>`<a class="contactItem" href="mailto:${esc(e)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></svg><span>${esc(e)}</span></a>`).join("")}${(s.phones||[]).map(p=>`<a class="contactItem" href="${telHref(p)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2z"/></svg><span>${esc(p)}</span></a>`).join("")}</address></div><div class="card" id="msgCard"><h3>Message a class teacher</h3><p class="muted">Tap a class. Your message goes to that class's teacher, with a copy to the school office.</p><div class="classBtns">${d.classes.map(c=>`<button type="button" class="classBtn" data-class="${esc(c.id)}" onclick="openClassMsg('${esc(c.id)}')">${esc(c.name)}</button>`).join("")}</div><form id="msgForm" class="formGrid" hidden><h4 class="fullRow" id="msgTo"></h4><input type="hidden" name="classId"><label>Your name<input name="name" required maxlength="80"></label><label>Phone or email<input name="contact" required maxlength="80" placeholder="So the teacher can reply"></label><label class="fullRow">Message<textarea name="message" required minlength="5" maxlength="1500"></textarea></label><div class="hp" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><button class="btn primary fullRow" id="msgSend">Send message</button></form></div></div></section>`}
function openClassMsg(id){const f=$("#msgForm");if(!f)return;f.hidden=false;f.elements["classId"].value=id;$("#msgTo").textContent="Message to the "+className(id)+" teacher";document.querySelectorAll(".classBtn").forEach(b=>b.classList.toggle("active",b.dataset.class===id));const rm=matchMedia("(prefers-reduced-motion: reduce)").matches;try{f.scrollIntoView({behavior:rm?"auto":"smooth",block:"center"})}catch{}f.elements["name"].focus({preventScroll:true})}
function bindContactForm(){const f=$("#msgForm");if(!f)return;f.onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f).entries()),btn=$("#msgSend");btn.disabled=true;btn.textContent="Sending...";try{await api("/api/public/message",{method:"POST",body:JSON.stringify(b)});toast("Message sent. The teacher will reply to you.");f.reset();f.hidden=true;document.querySelectorAll(".classBtn").forEach(x=>x.classList.remove("active"))}catch(err){toast(err.message)}btn.disabled=false;btn.textContent="Send message"}}

/* ---------- classes with class teacher ---------- */
async function tabClasses(){const [rows,teachers]=await Promise.all([api("/api/classes"),api("/api/teachers")]);window._classes=rows;window._teachersList=teachers;
return `<div class="panel"><div class="toolbar"><button class="btn primary" onclick="classForm()">+ Add class</button></div><p class="muted">Each class needs a class teacher. Parents and visitors who message a class reach that teacher.</p><div class="grid3">${rows.map(c=>{const t=teachers.find(x=>x.id===c.classTeacherId);return `<div class="card"><span class="eyebrow">${esc(c.section)}</span><h3>${esc(c.name)}</h3><p class="muted">Class teacher: <b>${esc(t?.name||"Not set")}</b></p><div class="actionsRow"><button class="btn ghost" onclick="classTeacherForm('${c.id}')">Set class teacher</button><button class="btn ghost" onclick="classSubjectsForm('${c.id}')">Subjects (${(c.defaultSubjectIds||[]).length})</button></div></div>`}).join("")}</div></div>`}
function classTeacherForm(id){const c=window._classes.find(x=>x.id===id),ts=window._teachersList||[];$("#dashContent").innerHTML=`<div class="panel">${backBtn("Classes")}<h3>Class teacher for ${esc(c.name)}</h3><form id="ctForm" class="formGrid"><label class="fullRow">Teacher<select name="classTeacherId"><option value="">— none —</option>${ts.map(t=>`<option value="${t.id}" ${c.classTeacherId===t.id?"selected":""}>${esc(t.name)}</option>`).join("")}</select></label><button class="btn primary fullRow">Save</button></form></div>`;$("#ctForm").onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());try{await api("/api/classes/"+id,{method:"PATCH",body:JSON.stringify(b)});toast("Class teacher saved");openTab("Classes")}catch(err){toast(err.message)}}}

/* ---------- messages (teachers, management, parents) ---------- */
const msgContact=m=>{const c=String(m.fromContact||"");if(!c)return"";if(c.includes("@"))return `<a href="mailto:${esc(c)}">${esc(c)}</a>`;return `<a href="${telHref(c)}">${esc(c)}</a> · <a target="_blank" rel="noopener" href="${waLink(c,"Hello "+m.fromName+", this is a reply from Masaba International Schools regarding your message.")}">WhatsApp</a>`};
async function tabMessages(){const u=getUser(),rows=await api("/api/messages"),kids=dashData?.children||[];window._msgs=rows;
const compose=u.role==="parent"?`<div class="panel"><h3>Message a class teacher</h3><form id="pmForm" class="formGrid" onsubmit="sendParentMessage(event)"><label class="fullRow">About<select name="studentId">${kids.map(s=>`<option value="${s.id}">${esc(s.name)} (${esc(className(s.classId))})</option>`).join("")}</select></label><label class="fullRow">Message<textarea name="text" required minlength="2" maxlength="1500"></textarea></label><button class="btn primary fullRow">Send</button></form></div>`:"";
return `${compose}<div class="panel"><h3>${u.role==="parent"?"Your conversations":"Messages"}</h3>${rows.map(m=>`<article class="thread"><div class="threadHead"><b>${esc(m.fromName)}</b><span class="pill ${m.status==="New"?"pillWarn":""}">${esc(m.status)}</span></div><small class="mini">${esc(className(m.classId))} · ${esc((m.createdAt||"").slice(0,10))}${u.role!=="parent"?" · "+msgContact(m):""}</small><p>${esc(m.text)}</p>${(m.replies||[]).map(r=>`<div class="reply ${r.byRole==="parent"?"mine":""}"><b>${esc(r.byName)}</b><small class="mini">${esc((r.at||"").slice(0,10))}</small><p>${esc(r.text)}</p></div>`).join("")}${m.status!=="Closed"||u.role==="parent"?`<div class="replyBox"><textarea id="rep_${m.id}" rows="2" placeholder="Write a reply..."></textarea><div class="actionsRow"><button class="btn primary" onclick="replyMsg('${m.id}')">Reply</button>${u.role!=="parent"&&m.status!=="Closed"?`<button class="btn ghost" onclick="closeMsg('${m.id}')">Mark done</button>`:""}</div></div>`:""}</article>`).join("")||"<div class='empty'>No messages yet.</div>"}</div>`}
async function sendParentMessage(e){e.preventDefault();const b=Object.fromEntries(new FormData(e.target).entries());try{await api("/api/messages",{method:"POST",body:JSON.stringify(b)});toast("Message sent");openTab("Messages")}catch(err){toast(err.message)}}
async function replyMsg(id){const t=$("#rep_"+id);if(!t||!t.value.trim())return toast("Write a reply first");try{await api("/api/messages/"+id+"/reply",{method:"POST",body:JSON.stringify({text:t.value})});toast("Reply sent");openTab("Messages")}catch(e){toast(e.message)}}
async function closeMsg(id){try{await api("/api/messages/"+id+"/close",{method:"POST",body:"{}"});toast("Marked as done");openTab("Messages")}catch(e){toast(e.message)}}

/* ---------- homepage image ---------- */
async function uploadHero(){const f=$("#heroFile").files[0];if(!f)return toast("Choose a photo first");try{const url=await uploadFile(f);await api("/api/settings",{method:"PATCH",body:JSON.stringify({heroImage:url})});toast("Homepage image updated");openTab("Settings")}catch(e){toast(e.message)}}
async function resetHero(){try{await api("/api/settings",{method:"PATCH",body:JSON.stringify({heroImage:""})});toast("Using the default homepage image");openTab("Settings")}catch(e){toast(e.message)}}

async function tabSubjects(){const rows=await api("/api/subjects");window._subjects=rows;const mg=isMgmt(),sorted=rows.slice().sort((a,b)=>(a.active===false)-(b.active===false));
return `<div class="panel"><div class="toolbar">${mg?`<button class="btn primary" onclick="subjectForm()">+ Add subject</button>`:""}</div>${mg?`<p class="muted mini">Hidden subjects disappear from every list but stay on old results. To give a class its subjects, open <b>Classes</b> and tap <b>Subjects</b>.</p>`:""}<div class="grid4">${sorted.map(s=>`<div class="card"><h3>${esc(s.name)}</h3><span class="pill ${s.active===false?"pillWarn":""}">${s.active===false?"Hidden":"Active"}</span>${mg?`<div class="actionsRow" style="margin-top:10px"><button class="btn ghost" onclick="renameSubject('${s.id}')">Rename</button><button class="btn ghost" onclick="toggleSubject('${s.id}',${s.active===false})">${s.active===false?"Show":"Hide"}</button></div>`:""}</div>`).join("")}</div></div>`}
async function renameSubject(id){const s=(window._subjects||[]).find(x=>x.id===id);const name=prompt("New name for this subject",s?.name||"");if(!name||!name.trim())return;try{await api("/api/subjects/"+id,{method:"PATCH",body:JSON.stringify({name:name.trim()})});toast("Renamed");openTab("Subjects")}catch(e){toast(e.message)}}
async function toggleSubject(id,show){try{await api("/api/subjects/"+id,{method:"PATCH",body:JSON.stringify({active:!!show})});toast(show?"Subject shown":"Subject hidden");openTab("Subjects")}catch(e){toast(e.message)}}
async function classSubjectsForm(id){const c=window._classes.find(x=>x.id===id),subs=(await api("/api/subjects")).filter(x=>x.active!==false),cur=c.defaultSubjectIds||[];
$("#dashContent").innerHTML=`<div class="panel">${backBtn("Classes")}<h3>Subjects for ${esc(c.name)}</h3><p class="muted">Tick the subjects every student in this class takes. Optional ones (for example Islamic Studies or Christian Religious Studies) can be set for individual students afterwards from the Students tab.</p><form id="csForm"><div class="checkGrid">${subs.map(x=>`<label class="check"><input type="checkbox" name="subjectIds" value="${x.id}" ${cur.includes(x.id)?"checked":""}>${esc(x.name)}</label>`).join("")}</div><label class="check" style="margin-top:14px"><input type="checkbox" name="apply" checked> Also apply to the students already in this class</label><button class="btn primary" style="margin-top:18px">Save subjects</button></form></div>`;
$("#csForm").onsubmit=async e=>{e.preventDefault();const ids=[...e.target.querySelectorAll('input[name="subjectIds"]:checked')].map(i=>i.value),apply=e.target.elements["apply"].checked;try{const r=await api("/api/classes/"+id+"/subjects",{method:"POST",body:JSON.stringify({subjectIds:ids,apply})});toast(apply?`Saved. Updated ${r.updated} student(s).`:"Saved");openTab("Classes")}catch(err){toast(err.message)}}}
async function contactEdit(kind,id){const t=kind==="teacher",rows=await api(t?"/api/teachers":"/api/parents"),r=rows.find(x=>x.id===id);if(!r)return;let classes=[],subs=[];if(t){[classes,subs]=await Promise.all([api("/api/classes"),api("/api/subjects")]);subs=subs.filter(x=>x.active!==false)}
$("#dashContent").innerHTML=`<div class="panel">${backBtn(t?"Teachers":"Parents")}<h3>Edit ${t?"teacher":"parent"}: ${esc(r.name)}</h3><form id="contactForm" class="formGrid"><label>Name<input name="name" value="${esc(r.name)}" required></label>${t?`<label>Staff ID<input name="staffId" value="${esc(r.staffId||"")}"></label>`:""}<label>Phone<input name="phone" value="${esc(r.phone||"")}"></label><label>Email<input name="email" type="email" value="${esc(r.email||"")}"></label>${t?`<label>School email (optional)<input name="schoolEmail" type="email" value="${esc(r.schoolEmail||"")}"></label><div class="fullRow"><b>Classes taught</b><div class="checkGrid">${classes.map(c=>`<label class="check"><input type="checkbox" name="classIds" value="${c.id}" ${(r.classIds||[]).includes(c.id)?"checked":""}>${esc(c.name)}</label>`).join("")}</div></div><div class="fullRow"><b>Subjects taught</b><div class="checkGrid">${subs.map(x=>`<label class="check"><input type="checkbox" name="subjectIds" value="${x.id}" ${(r.subjectIds||[]).includes(x.id)?"checked":""}>${esc(x.name)}</label>`).join("")}</div></div>`:""}<button class="btn primary fullRow">Save</button></form></div>`;
$("#contactForm").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),b=Object.fromEntries(fd.entries());if(t){b.classIds=fd.getAll("classIds");b.subjectIds=fd.getAll("subjectIds")}try{await api((t?"/api/teachers/":"/api/parents/")+id,{method:"PATCH",body:JSON.stringify(b)});toast("Saved");openTab(t?"Teachers":"Parents")}catch(err){toast(err.message)}}}
async function render(){const route=location.hash.replace("#","")||"home";try{if(route==="home")await renderHome();else if(route==="portal")await renderPortal();else if(route==="admissions"){app.innerHTML=await admissions();$("#admissionForm").onsubmit=async e=>{e.preventDefault();try{await api("/api/admissions",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target).entries()))});e.target.reset();toast("Admission enquiry submitted")}catch(err){toast(err.message)}}}else if(route==="gallery")app.innerHTML=await galleryPage();else if(route==="stem"){await ensurePublic();app.innerHTML=stemPage()}else if(route==="contact"){app.innerHTML=await contactPage();bindContactForm()}else if(route==="news")app.innerHTML=await news();else if(route==="events")app.innerHTML=await events();else {await ensurePublic();app.innerHTML=staticPage(route)}}catch(e){app.innerHTML=`<section class="section"><div class="panel"><h2>Something went wrong</h2><p>${esc(e.message)}</p></div></section>`}if(!document.body.classList.contains("portalMode")){app.classList.remove("routeIn");void app.offsetWidth;app.classList.add("routeIn")}else app.classList.remove("routeIn")}
window.addEventListener("hashchange",render);render();
